sec(id='airfoil', lv=['cc', 'ug'], refs=['anderson_fa', 'anderson_if', 'grc'],
 t=T('Lift, the airfoil and thin-airfoil theory', 'Portance, profil et théorie des profils minces', 'Sustentación, perfil y teoría del perfil delgado', 'الرفع والمقطع الجناحي ونظرية المقطع الرقيق', 'Portanza, profilo e teoria del profilo sottile'),
 eli=T('Hold your hand out of a car window and tilt it up a little: the air pushes it up. A wing does the same thing, turning the air downward so the air pushes the wing up.', 'Sors ta main par la fenêtre de la voiture et incline-la un peu : l\u2019air la pousse vers le haut. Une aile fait pareil : elle dévie l\u2019air vers le bas, et l\u2019air la pousse vers le haut.', 'Saca la mano por la ventanilla del coche e inclínala un poco: el aire la empuja hacia arriba. Un ala hace lo mismo: desvía el aire hacia abajo y el aire la empuja hacia arriba.', 'أخرج يدك من نافذة السيارة وأملها قليلًا إلى الأعلى: يدفعها الهواء لأعلى. الجناح يفعل الشيء نفسه: يحرف الهواء إلى الأسفل فيدفعه الهواء إلى الأعلى.', 'Metti la mano fuori dal finestrino e inclinala un po\u2019: l\u2019aria la spinge su. Un\u2019ala fa lo stesso: devia l\u2019aria verso il basso e l\u2019aria la spinge verso l\u2019alto.'),
 obj=T('Use the lift equation; state the thin-airfoil result c_l = 2\u03c0\u03b1; compute a stall speed.', 'Utiliser l\u2019équation de portance ; énoncer le résultat des profils minces c_l = 2\u03c0\u03b1 ; calculer une vitesse de décrochage.', 'Usar la ecuación de sustentación; enunciar el resultado del perfil delgado c_l = 2\u03c0\u03b1; calcular una velocidad de pérdida.', 'استخدام معادلة الرفع؛ صياغة نتيجة المقطع الرقيق c_l = 2\u03c0\u03b1؛ حساب سرعة الانهيار.', 'Usare l\u2019equazione della portanza; enunciare il risultato del profilo sottile c_l = 2\u03c0\u03b1; calcolare una velocità di stallo.'),
 pre=T('Dynamic pressure, radians, integrals of trigonometric functions (for the derivation).', 'Pression dynamique, radians, intégrales trigonométriques (pour la démonstration).', 'Presión dinámica, radianes, integrales trigonométricas (para la deducción).', 'الضغط الديناميكي، الراديان، تكاملات الدوال المثلثية (للاشتقاق).', 'Pressione dinamica, radianti, integrali trigonometrici (per la dimostrazione).'),
 body=T('Lift grows with air density, the square of speed, wing area and a lift coefficient that depends on angle of attack. Thin-airfoil theory models the wing as a sheet of vortices and predicts the slope: 2\u03c0 per radian.', 'La portance croît avec la densité de l\u2019air, le carré de la vitesse, la surface alaire et un coefficient de portance qui dépend de l\u2019incidence. La théorie des profils minces modélise l\u2019aile comme une nappe de tourbillons et prédit la pente : 2\u03c0 par radian.', 'La sustentación crece con la densidad del aire, el cuadrado de la velocidad, la superficie alar y un coeficiente que depende del ángulo de ataque. La teoría del perfil delgado modela el ala como una lámina de vórtices y predice la pendiente: 2\u03c0 por radián.', 'يزداد الرفع مع كثافة الهواء ومربع السرعة ومساحة الجناح ومعامل رفع يعتمد على زاوية الهجوم. تنمذج نظرية المقطع الرقيق الجناح كصفيحة من الدوامات وتتنبأ بالميل: 2\u03c0 لكل راديان.', 'La portanza cresce con la densità dell\u2019aria, il quadrato della velocità, la superficie alare e un coefficiente che dipende dall\u2019incidenza. La teoria del profilo sottile modella l\u2019ala come uno strato di vortici e prevede la pendenza: 2\u03c0 per radiante.'),
 steps=[(r'L=\tfrac12\rho V^2 S\,C_L', T('Lift equation (definition of C_L).', 'Équation de portance (définition de C_L).', 'Ecuación de sustentación (definición de C_L).', 'معادلة الرفع (تعريف C_L).', 'Equazione della portanza (definizione di C_L).')),
        (r'\frac{1}{2\pi}\int_0^\pi\frac{\gamma(\theta)\sin\theta}{\cos\theta-\cos\theta_0}\,d\theta=V_\infty\left(\alpha-\frac{dz}{dx}\right)', T('Thin-airfoil integral equation for the vortex sheet strength \u03b3.', 'Équation intégrale des profils minces pour l\u2019intensité \u03b3 de la nappe.', 'Ecuación integral del perfil delgado para la intensidad \u03b3 de la lámina.', 'معادلة المقطع الرقيق التكاملية لشدة صفيحة الدوامات \u03b3.', 'Equazione integrale del profilo sottile per l\u2019intensità \u03b3 dello strato.')),
        (r'\gamma(\theta)=2\alpha V_\infty\frac{1+\cos\theta}{\sin\theta}\;\Rightarrow\;c_l=\frac{2\Gamma}{V_\infty c}=2\pi\alpha', T('Symmetric airfoil solution and Kutta\u2013Joukowski.', 'Solution du profil symétrique et Kutta\u2013Joukowski.', 'Solución del perfil simétrico y Kutta\u2013Joukowski.', 'حل المقطع المتماثل وقانون كوتا\u2013جوكوفسكي.', 'Soluzione del profilo simmetrico e Kutta\u2013Joukowski.')),
        (r'V_{s}=\sqrt{\frac{2W}{\rho S C_{L,\max}}}', T('Stall speed: lift equals weight at the maximum C_L.', 'Vitesse de décrochage : portance = poids au C_L maximal.', 'Velocidad de pérdida: sustentación = peso con C_L máximo.', 'سرعة الانهيار: الرفع يساوي الوزن عند أقصى C_L.', 'Velocità di stallo: portanza = peso al C_L massimo.'))],
 we=we(T('Generic light aircraft: m = 1100 kg, S = 16.2 m\u00b2, C_L,max = 1.6, sea level (\u03c1 = 1.225 kg/m\u00b3).', 'Avion léger générique : m = 1100 kg, S = 16,2 m\u00b2, C_L,max = 1,6, niveau de la mer (\u03c1 = 1,225 kg/m\u00b3).', 'Avioneta genérica: m = 1100 kg, S = 16,2 m\u00b2, C_L,max = 1,6, nivel del mar (\u03c1 = 1,225 kg/m\u00b3).', 'طائرة خفيفة عامة: m = 1100 كغ، S = 16.2 م\u00b2، C_L,max = 1.6، مستوى سطح البحر (\u03c1 = 1.225 كغ/م\u00b3).', 'Aereo leggero generico: m = 1100 kg, S = 16,2 m\u00b2, C_L,max = 1,6, livello del mare (\u03c1 = 1,225 kg/m\u00b3).'),
   T('Stall speed; and c_l of a thin symmetric airfoil at 5\u00b0.', 'Vitesse de décrochage ; et c_l d\u2019un profil mince symétrique à 5\u00b0.', 'Velocidad de pérdida; y c_l de un perfil delgado simétrico a 5\u00b0.', 'سرعة الانهيار؛ و c_l لمقطع رقيق متماثل عند 5\u00b0.', 'Velocità di stallo; e c_l di un profilo sottile simmetrico a 5\u00b0.'),
   T('Set L = W at C_L,max; convert 5\u00b0 to radians for 2\u03c0\u03b1.', 'Poser L = W à C_L,max ; convertir 5\u00b0 en radians pour 2\u03c0\u03b1.', 'Igualar L = W con C_L,max; pasar 5\u00b0 a radianes para 2\u03c0\u03b1.', 'نضع L = W عند C_L,max؛ ونحوّل 5\u00b0 إلى راديان في 2\u03c0\u03b1.', 'Porre L = W a C_L,max; convertire 5\u00b0 in radianti per 2\u03c0\u03b1.'),
   ['W = 1100 \u00b7 9.80665 = 10787 N', 'V_s = \u221a(2 \u00b7 10787 / (1.225 \u00b7 16.2 \u00b7 1.6)) = {a_vs:2} m/s', '\u03b1 = 5\u00b0 = 0.08727 rad \u2192 c_l = 2\u03c0\u03b1 = {a_cl5:4}'],
   T('V_s = {a_vs:1} m/s ({a_vs_kn:0} kn); c_l = {a_cl5:3}.', 'V_s = {a_vs:1} m/s ({a_vs_kn:0} nœuds) ; c_l = {a_cl5:3}.', 'V_s = {a_vs:1} m/s ({a_vs_kn:0} nudos); c_l = {a_cl5:3}.', 'V_s = {a_vs:1} م/ث ({a_vs_kn:0} عقدة)؛ c_l = {a_cl5:3}.', 'V_s = {a_vs:1} m/s ({a_vs_kn:0} nodi); c_l = {a_cl5:3}.'),
   T('About 50 knots is typical of published stall speeds for light training aircraft, and 0.55 is close to measured c_l for thin symmetric sections at 5\u00b0.', 'Environ 50 nœuds est typique des vitesses de décrochage publiées pour les avions-écoles légers, et 0,55 est proche du c_l mesuré pour des profils minces symétriques à 5\u00b0.', 'Unos 50 nudos es típico de las velocidades de pérdida publicadas para avionetas de instrucción, y 0,55 se acerca al c_l medido en perfiles delgados simétricos a 5\u00b0.', 'نحو 50 عقدة قيمة نموذجية لسرعات الانهيار المنشورة لطائرات التدريب الخفيفة، و0.55 قريب من c_l المقاس للمقاطع الرقيقة المتماثلة عند 5\u00b0.', 'Circa 50 nodi è tipico delle velocità di stallo pubblicate per gli aerei scuola leggeri, e 0,55 è vicino al c_l misurato per profili sottili simmetrici a 5\u00b0.'),
   T('Stall speed sets runway length and approach speed; flaps raise C_L,max to land slower.', 'La vitesse de décrochage fixe la longueur de piste et la vitesse d\u2019approche ; les volets augmentent C_L,max pour atterrir plus lentement.', 'La velocidad de pérdida fija la longitud de pista y la velocidad de aproximación; los flaps suben C_L,max para aterrizar más lento.', 'تحدد سرعة الانهيار طول المدرج وسرعة الاقتراب؛ وترفع القلابات C_L,max للهبوط بسرعة أقل.', 'La velocità di stallo fissa la lunghezza della pista e la velocità di avvicinamento; i flap alzano C_L,max per atterrare più piano.'),
   'import math\nm, S, clmax, rho, g0 = 1100, 16.2, 1.6, 1.225, 9.80665\nVs = math.sqrt(2*m*g0 / (rho*S*clmax))\nprint(Vs, Vs/0.514444, 2*math.pi*math.radians(5))'),
 np=[npq(T('Same aircraft at 1500 m ISA altitude: stall speed (true airspeed) in m/s?', 'Même avion à 1500 m d\u2019altitude ISA : vitesse de décrochage (vitesse vraie) en m/s ?', 'Mismo avión a 1500 m ISA: ¿velocidad de pérdida (verdadera) en m/s?', 'الطائرة نفسها على ارتفاع 1500 م قياسي: سرعة الانهيار (السرعة الحقيقية) بوحدة م/ث؟', 'Stesso aereo a 1500 m ISA: velocità di stallo (vera) in m/s?'), A.examples()['a_vs5'], 'm/s',
   [T('Find ISA \u03c1 at 1500 m first.', 'Trouvez d\u2019abord \u03c1 ISA à 1500 m.', 'Halla primero \u03c1 ISA a 1500 m.', 'أوجد أولًا \u03c1 القياسية عند 1500 م.', 'Trova prima \u03c1 ISA a 1500 m.'), T('V_s scales as 1/\u221a\u03c1.', 'V_s varie comme 1/\u221a\u03c1.', 'V_s va como 1/\u221a\u03c1.', 'تتناسب V_s مع 1/\u221a\u03c1.', 'V_s va come 1/\u221a\u03c1.')],
   T('\u03c1(1500 m) = {b:4} kg/m\u00b3, so V_s = {a:2} m/s (the indicated stall speed stays the same).', '\u03c1(1500 m) = {b:4} kg/m\u00b3, donc V_s = {a:2} m/s (la vitesse indiquée de décrochage reste la même).', '\u03c1(1500 m) = {b:4} kg/m\u00b3, luego V_s = {a:2} m/s (la velocidad indicada de pérdida no cambia).', '\u03c1(1500 م) = {b:4} كغ/م\u00b3، إذن V_s = {a:2} م/ث (وتبقى سرعة الانهيار المؤشرة كما هي).', '\u03c1(1500 m) = {b:4} kg/m\u00b3, quindi V_s = {a:2} m/s (la velocità indicata di stallo resta uguale).'))],
 prac=[(T('Why does thin-airfoil theory fail above about 12\u201315\u00b0?', 'Pourquoi la théorie des profils minces échoue-t-elle au-delà d\u2019environ 12\u201315\u00b0 ?', '¿Por qué falla la teoría del perfil delgado por encima de unos 12\u201315\u00b0?', 'لماذا تفشل نظرية المقطع الرقيق فوق نحو 12\u201315\u00b0؟', 'Perché la teoria del profilo sottile fallisce oltre circa 12\u201315\u00b0?'), T('It assumes attached, inviscid flow and small angles; at high \u03b1 the boundary layer separates (stall).', 'Elle suppose un écoulement attaché, non visqueux et de petits angles ; à forte incidence la couche limite décolle (décrochage).', 'Supone flujo adherido, no viscoso y ángulos pequeños; con \u03b1 alto la capa límite se desprende (pérdida).', 'تفترض جريانًا ملتصقًا وعديم اللزوجة وزوايا صغيرة؛ وعند \u03b1 كبيرة تنفصل الطبقة الحدية (الانهيار).', 'Presuppone flusso attaccato, non viscoso e angoli piccoli; ad alto \u03b1 lo strato limite si separa (stallo).'))],
 mist=T('Putting \u03b1 in degrees into 2\u03c0\u03b1. Use radians.', 'Mettre \u03b1 en degrés dans 2\u03c0\u03b1. Utilisez les radians.', 'Meter \u03b1 en grados en 2\u03c0\u03b1. Usa radianes.', 'وضع \u03b1 بالدرجات في 2\u03c0\u03b1. استخدم الراديان.', 'Mettere \u03b1 in gradi in 2\u03c0\u03b1. Usa i radianti.'))
S[-1]['np'][0]['extra'] = dict(b=A.isa(1500)[2])
sec(id='wing', lv=['ug'], refs=['anderson_fa', 'ocw100'],
 t=T('Finite wings: lifting-line theory and induced drag', 'Ailes finies : ligne portante et traînée induite', 'Alas finitas: línea sustentadora y resistencia inducida', 'الأجنحة المحدودة: نظرية خط الرفع والسحب المستحث', 'Ali finite: linea portante e resistenza indotta'),
 eli=T('Air leaks around the wing tips from the high-pressure bottom to the low-pressure top and makes spinning tornadoes behind the plane. Long, skinny wings leak less, like a glider\u2019s.', 'L\u2019air s\u2019échappe autour du bout des ailes, du dessous (haute pression) vers le dessus (basse pression), et forme des tourbillons derrière l\u2019avion. Les ailes longues et fines fuient moins, comme celles d\u2019un planeur.', 'El aire se escapa por las puntas del ala desde abajo (alta presión) hacia arriba (baja presión) y forma remolinos detrás del avión. Las alas largas y finas pierden menos, como las de un planeador.', 'يتسرب الهواء حول طرفي الجناح من الأسفل (ضغط عالٍ) إلى الأعلى (ضغط منخفض) فيصنع دوامات خلف الطائرة. الأجنحة الطويلة النحيلة تسرّب أقل، مثل أجنحة الطائرة الشراعية.', 'L\u2019aria sfugge attorno alle estremità dell\u2019ala, da sotto (alta pressione) a sopra (bassa pressione), e forma vortici dietro l\u2019aereo. Le ali lunghe e sottili perdono meno, come quelle di un aliante.'),
 obj=T('Derive induced drag C_Di = C_L\u00b2/(\u03c0eAR); compute the finite-wing lift slope from lifting-line theory.', 'Établir la traînée induite C_Di = C_L\u00b2/(\u03c0eAR) ; calculer la pente de portance d\u2019une aile finie par la ligne portante.', 'Deducir la resistencia inducida C_Di = C_L\u00b2/(\u03c0eAR); calcular la pendiente de sustentación de un ala finita con la línea sustentadora.', 'اشتقاق السحب المستحث C_Di = C_L\u00b2/(\u03c0eAR)؛ حساب ميل الرفع للجناح المحدود من نظرية خط الرفع.', 'Ricavare la resistenza indotta C_Di = C_L\u00b2/(\u03c0eAR); calcolare la pendenza di portanza di un\u2019ala finita con la linea portante.'),
 pre=T('Thin-airfoil theory, Fourier series, Biot\u2013Savart law.', 'Théorie des profils minces, séries de Fourier, loi de Biot\u2013Savart.', 'Teoría del perfil delgado, series de Fourier, ley de Biot\u2013Savart.', 'نظرية المقطع الرقيق، متسلسلات فورييه، قانون بيو\u2013سافار.', 'Teoria del profilo sottile, serie di Fourier, legge di Biot\u2013Savart.'),
 body=T('Trailing vortices induce a downwash that tilts the local lift backward. That backward component is induced drag, the price of making lift with a wing of finite span.', 'Les tourbillons marginaux induisent une déflexion vers le bas qui incline la portance locale vers l\u2019arrière. Cette composante arrière est la traînée induite, le prix de la portance d\u2019une aile d\u2019envergure finie.', 'Los vórtices de punta inducen una deflexión hacia abajo que inclina la sustentación local hacia atrás. Esa componente hacia atrás es la resistencia inducida, el precio de sustentar con un ala de envergadura finita.', 'تولّد الدوامات الطرفية تيارًا هابطًا يميل الرفع المحلي إلى الخلف. هذه المركبة الخلفية هي السحب المستحث، ثمن توليد الرفع بجناح محدود الامتداد.', 'I vortici d\u2019estremità inducono un downwash che inclina all\u2019indietro la portanza locale. Quella componente all\u2019indietro è la resistenza indotta, il prezzo della portanza con un\u2019ala di apertura finita.'),
 steps=[(r'\Gamma(\theta)=2bV_\infty\sum_{n}A_n\sin n\theta,\qquad y=-\tfrac b2\cos\theta', T('Fourier series for the circulation along the span.', 'Série de Fourier de la circulation le long de l\u2019envergure.', 'Serie de Fourier de la circulación a lo largo de la envergadura.', 'متسلسلة فورييه للدوران على امتداد الجناح.', 'Serie di Fourier della circolazione lungo l\u2019apertura.')),
        (r'C_L=\pi AR\,A_1,\qquad C_{D_i}=\pi AR\sum_n nA_n^2=\frac{C_L^2}{\pi e AR}', T('Lift needs only A\u2081; every other term adds drag (e \u2264 1).', 'La portance ne dépend que de A\u2081 ; chaque autre terme ajoute de la traînée (e \u2264 1).', 'La sustentación solo usa A\u2081; los demás términos añaden resistencia (e \u2264 1).', 'يعتمد الرفع على A\u2081 فقط؛ وكل حد آخر يضيف سحبًا (e \u2264 1).', 'La portanza usa solo A\u2081; ogni altro termine aggiunge resistenza (e \u2264 1).')),
        (r'a=\frac{a_0}{1+a_0/(\pi e AR)}', T('Finite-wing lift slope (elliptic-type correction).', 'Pente de portance de l\u2019aile finie (correction de type elliptique).', 'Pendiente de sustentación del ala finita (corrección de tipo elíptico).', 'ميل رفع الجناح المحدود (تصحيح من النوع الإهليلجي).', 'Pendenza di portanza dell\u2019ala finita (correzione di tipo ellittico).'))],
 we=we(T('AR = 9, Oswald efficiency e = 0.8, C_L = 0.5, a\u2080 = 2\u03c0 per rad.', 'AR = 9, coefficient d\u2019Oswald e = 0,8, C_L = 0,5, a\u2080 = 2\u03c0 par rad.', 'AR = 9, eficiencia de Oswald e = 0,8, C_L = 0,5, a\u2080 = 2\u03c0 por rad.', 'AR = 9، كفاءة أوزوالد e = 0.8، C_L = 0.5، a\u2080 = 2\u03c0 لكل راديان.', 'AR = 9, efficienza di Oswald e = 0,8, C_L = 0,5, a\u2080 = 2\u03c0 per rad.'),
   T('C_Di and the wing lift slope a.', 'C_Di et la pente de portance a.', 'C_Di y la pendiente a.', 'C_Di وميل الرفع a.', 'C_Di e la pendenza a.'),
   T('Plug into the two lifting-line results.', 'Appliquer les deux résultats de la ligne portante.', 'Sustituir en los dos resultados de la línea sustentadora.', 'نعوّض في نتيجتي خط الرفع.', 'Sostituire nei due risultati della linea portante.'),
   ['\u03c0eAR = \u03c0 \u00b7 0.8 \u00b7 9 = 22.62', 'C_Di = 0.5\u00b2 / 22.62 = {a_cdi:5}', 'a = 2\u03c0 / (1 + 2\u03c0/22.62) = {a_cla:3} /rad'],
   T('C_Di = {a_cdi:4}; a = {a_cla:2} per radian.', 'C_Di = {a_cdi:4} ; a = {a_cla:2} par radian.', 'C_Di = {a_cdi:4}; a = {a_cla:2} por radián.', 'C_Di = {a_cdi:4}؛ a = {a_cla:2} لكل راديان.', 'C_Di = {a_cdi:4}; a = {a_cla:2} per radiante.'),
   T('a is less than 2\u03c0 and tends to 2\u03c0 as AR \u2192 \u221e, as it must.', 'a est inférieur à 2\u03c0 et tend vers 2\u03c0 quand AR \u2192 \u221e, comme il se doit.', 'a es menor que 2\u03c0 y tiende a 2\u03c0 cuando AR \u2192 \u221e, como debe.', 'a أصغر من 2\u03c0 ويؤول إلى 2\u03c0 عندما AR \u2192 \u221e كما يجب.', 'a è minore di 2\u03c0 e tende a 2\u03c0 per AR \u2192 \u221e, come deve.'),
   T('With C_D0 = 0.02, induced drag here is about a third of the total, which is why gliders and long-range airliners use high aspect ratios and winglets.', 'Avec C_D0 = 0,02, la traînée induite vaut ici environ un tiers du total : d\u2019où les grands allongements et les winglets des planeurs et avions long-courriers.', 'Con C_D0 = 0,02, la resistencia inducida es aquí cerca de un tercio del total: por eso planeadores y aviones de largo alcance usan gran alargamiento y winglets.', 'مع C_D0 = 0.02 يكون السحب المستحث هنا نحو ثلث السحب الكلي، ولهذا تستخدم الطائرات الشراعية وطائرات المدى الطويل نسب باع عالية وجنيحات طرفية.', 'Con C_D0 = 0,02, la resistenza indotta qui è circa un terzo del totale: per questo alianti e aerei a lungo raggio usano grandi allungamenti e winglet.'),
   'import math\nAR, e, CL, a0 = 9, 0.8, 0.5, 2*math.pi\nprint(CL**2/(math.pi*e*AR), a0/(1 + a0/(math.pi*e*AR)))'),
 np=[npq(T('Same wing, AR raised to 12 (e = 0.8, C_L = 0.5): C_Di?', 'Même aile, AR porté à 12 (e = 0,8, C_L = 0,5) : C_Di ?', 'Misma ala con AR = 12 (e = 0,8, C_L = 0,5): ¿C_Di?', 'الجناح نفسه مع رفع AR إلى 12 (e = 0.8، C_L = 0.5): كم C_Di؟', 'Stessa ala con AR = 12 (e = 0,8, C_L = 0,5): C_Di?'), A.cdi(0.5, 12, 0.8), '',
   [T('C_Di = C_L\u00b2/(\u03c0eAR).', 'C_Di = C_L\u00b2/(\u03c0eAR).', 'C_Di = C_L\u00b2/(\u03c0eAR).', 'C_Di = C_L\u00b2/(\u03c0eAR).', 'C_Di = C_L\u00b2/(\u03c0eAR).')],
   T('C_Di = 0.25/(\u03c0 \u00b7 0.8 \u00b7 12) = {a:5}, 25% less than at AR = 9.', 'C_Di = 0,25/(\u03c0 \u00b7 0,8 \u00b7 12) = {a:5}, 25 % de moins qu\u2019à AR = 9.', 'C_Di = 0,25/(\u03c0 \u00b7 0,8 \u00b7 12) = {a:5}, un 25 % menos que con AR = 9.', 'C_Di = 0.25/(\u03c0 \u00b7 0.8 \u00b7 12) = {a:5}، أقل بنسبة 25% منه عند AR = 9.', 'C_Di = 0,25/(\u03c0 \u00b7 0,8 \u00b7 12) = {a:5}, il 25% in meno che con AR = 9.'))],
 prac=[(T('Which spanwise lift distribution gives e = 1?', 'Quelle répartition de portance en envergure donne e = 1 ?', '¿Qué distribución de sustentación en envergadura da e = 1?', 'أي توزيع للرفع على الامتداد يعطي e = 1؟', 'Quale distribuzione di portanza lungo l\u2019apertura dà e = 1?'), T('The elliptic distribution (only A\u2081 \u2260 0), which also gives uniform downwash.', 'La répartition elliptique (seul A\u2081 \u2260 0), qui donne aussi une déflexion uniforme.', 'La distribución elíptica (solo A\u2081 \u2260 0), que además da deflexión uniforme.', 'التوزيع الإهليلجي (A\u2081 فقط لا يساوي صفرًا)، وهو يعطي أيضًا تيارًا هابطًا منتظمًا.', 'La distribuzione ellittica (solo A\u2081 \u2260 0), che dà anche downwash uniforme.'))],
 mist=T('Using the 2D slope 2\u03c0 for a whole wing; a finite wing\u2019s slope is lower.', 'Utiliser la pente 2D 2\u03c0 pour toute une aile ; la pente d\u2019une aile finie est plus faible.', 'Usar la pendiente 2D 2\u03c0 para un ala entera; la de un ala finita es menor.', 'استخدام الميل ثنائي الأبعاد 2\u03c0 لجناح كامل؛ ميل الجناح المحدود أقل.', 'Usare la pendenza 2D 2\u03c0 per un\u2019ala intera; quella di un\u2019ala finita è minore.'))
sec(id='perf', lv=['ug'], refs=['anderson_if', 'grc'],
 t=T('Aircraft performance: best glide and the Breguet range equation', 'Performances : finesse maximale et équation de Breguet', 'Actuaciones: máxima eficiencia y ecuación de Breguet', 'أداء الطائرات: أفضل انزلاق ومعادلة بريغيه للمدى', 'Prestazioni: massima efficienza ed equazione di Breguet'),
 eli=T('An airplane is like a bike: there is a best speed where you go farthest for the least effort. Go too slow and you work hard to stay up; go too fast and the wind pushes back.', 'Un avion, c\u2019est comme un vélo : il existe une vitesse idéale pour aller le plus loin avec le moins d\u2019effort. Trop lent, on peine à rester en l\u2019air ; trop vite, le vent freine.', 'Un avión es como una bici: hay una velocidad ideal para llegar más lejos con menos esfuerzo. Muy lento, cuesta mantenerse arriba; muy rápido, el viento frena.', 'الطائرة مثل الدراجة: هناك سرعة مثالية تقطع بها أبعد مسافة بأقل جهد. إذا أبطأت كثيرًا تتعب لتبقى في الجو، وإذا أسرعت كثيرًا يدفعك الهواء إلى الخلف.', 'Un aereo è come una bici: c\u2019è una velocità ideale per andare più lontano con meno fatica. Troppo lento e fatichi a restare su; troppo veloce e il vento ti frena.'),
 obj=T('Use the drag polar to find maximum L/D by calculus; integrate the Breguet range equation for a jet.', 'Utiliser la polaire pour trouver la finesse maximale par le calcul différentiel ; intégrer l\u2019équation de Breguet pour un avion à réaction.', 'Usar la polar para hallar la máxima L/D con cálculo; integrar la ecuación de Breguet para un reactor.', 'استخدام القطبية لإيجاد أقصى L/D بالتفاضل؛ تكامل معادلة بريغيه لطائرة نفاثة.', 'Usare la polare per trovare la massima L/D col calcolo; integrare l\u2019equazione di Breguet per un jet.'),
 pre=T('Derivatives and optimisation, integrals of 1/W, induced drag.', 'Dérivées et optimisation, intégrale de 1/W, traînée induite.', 'Derivadas y optimización, integral de 1/W, resistencia inducida.', 'المشتقات والأمثلية، تكامل 1/W، السحب المستحث.', 'Derivate e ottimizzazione, integrale di 1/W, resistenza indotta.'),
 body=T('Drag has a part that grows with speed (friction, C_D0) and a part that shrinks with speed (induced). The best L/D is where they are equal; range then depends on L/D, engine efficiency and how much fuel is burned.', 'La traînée a une part qui croît avec la vitesse (frottement, C_D0) et une part qui décroît (induite). La meilleure finesse est là où elles sont égales ; l\u2019autonomie dépend alors de la finesse, du rendement moteur et du carburant brûlé.', 'La resistencia tiene una parte que crece con la velocidad (fricción, C_D0) y otra que decrece (inducida). La mejor L/D está donde son iguales; el alcance depende de L/D, de la eficiencia del motor y del combustible quemado.', 'للسحب جزء يزداد مع السرعة (الاحتكاك، C_D0) وجزء يتناقص معها (المستحث). أفضل L/D حيث يتساويان؛ ويعتمد المدى بعدها على L/D وكفاءة المحرك وكمية الوقود المحترق.', 'La resistenza ha una parte che cresce con la velocità (attrito, C_D0) e una che cala (indotta). La migliore L/D è dove si uguagliano; l\u2019autonomia dipende poi da L/D, dal rendimento del motore e dal carburante bruciato.'),
 steps=[(r'C_D=C_{D_0}+kC_L^2,\qquad k=\frac{1}{\pi eAR}', T('Parabolic drag polar.', 'Polaire parabolique.', 'Polar parabólica.', 'القطبية القطعية المكافئة.', 'Polare parabolica.')),
        (r'\frac{d}{dC_L}\!\left(\frac{C_L}{C_D}\right)=0\;\Rightarrow\;C_{D_0}=kC_L^2,\qquad \left(\frac{L}{D}\right)_{\max}=\frac{1}{2\sqrt{kC_{D_0}}}', T('Maximise L/D: friction drag equals induced drag.', 'Maximiser L/D : traînée de frottement = traînée induite.', 'Maximizar L/D: resistencia de fricción = inducida.', 'نعظّم L/D: سحب الاحتكاك يساوي المستحث.', 'Massimizzare L/D: resistenza d\u2019attrito = indotta.')),
        (r'-\frac{dW}{dt}=c\,T=c\,\frac{W}{L/D}\;\Rightarrow\;R=\int V\,dt=\frac{V}{c}\frac{L}{D}\ln\frac{W_i}{W_f}', T('Fuel burn rate c (TSFC) at constant V and L/D; integrate.', 'Débit de carburant c (consommation spécifique) à V et L/D constants ; intégrer.', 'Consumo c (TSFC) con V y L/D constantes; integrar.', 'معدل حرق الوقود c (الاستهلاك النوعي) مع ثبات V و L/D؛ نكامل.', 'Consumo c (TSFC) a V e L/D costanti; integrare.'))],
 we=we(T('AR = 9, e = 0.8, C_D0 = 0.02. Generic jet: V = 230 m/s, c = 0.6 per hour, L/D = 17, W_i/W_f = 1.25.', 'AR = 9, e = 0,8, C_D0 = 0,02. Jet générique : V = 230 m/s, c = 0,6 par heure, L/D = 17, W_i/W_f = 1,25.', 'AR = 9, e = 0,8, C_D0 = 0,02. Reactor genérico: V = 230 m/s, c = 0,6 por hora, L/D = 17, W_i/W_f = 1,25.', 'AR = 9، e = 0.8، C_D0 = 0.02. نفاثة عامة: V = 230 م/ث، c = 0.6 لكل ساعة، L/D = 17، W_i/W_f = 1.25.', 'AR = 9, e = 0,8, C_D0 = 0,02. Jet generico: V = 230 m/s, c = 0,6 all\u2019ora, L/D = 17, W_i/W_f = 1,25.'),
   T('(L/D)max, the C_L where it occurs, and the jet\u2019s range.', '(L/D)max, le C_L correspondant et l\u2019autonomie du jet.', '(L/D)max, el C_L donde ocurre y el alcance del reactor.', '(L/D)max و C_L المقابل ومدى النفاثة.', '(L/D)max, il C_L corrispondente e l\u2019autonomia del jet.'),
   T('k from AR and e; optimum formula; Breguet with c in 1/s.', 'k à partir de AR et e ; formule de l\u2019optimum ; Breguet avec c en 1/s.', 'k con AR y e; fórmula del óptimo; Breguet con c en 1/s.', 'k من AR و e؛ صيغة الأمثل؛ بريغيه مع c بوحدة 1/ث.', 'k da AR ed e; formula dell\u2019ottimo; Breguet con c in 1/s.'),
   ['k = 1/(\u03c0 \u00b7 0.8 \u00b7 9) = {a_k:5}', '(L/D)max = 1/(2\u221a(k \u00b7 0.02)) = {a_ldmax:2}', 'C_L* = \u221a(C_D0/k) = {a_clstar:3}', 'R = (230 / (0.6/3600)) \u00b7 17 \u00b7 ln 1.25 = {a_range_km:0} km'],
   T('(L/D)max = {a_ldmax:1} at C_L = {a_clstar:2}; range = {a_range_km:0} km ({a_range_nmi:0} nmi).', '(L/D)max = {a_ldmax:1} à C_L = {a_clstar:2} ; autonomie = {a_range_km:0} km ({a_range_nmi:0} NM).', '(L/D)max = {a_ldmax:1} con C_L = {a_clstar:2}; alcance = {a_range_km:0} km ({a_range_nmi:0} NM).', '(L/D)max = {a_ldmax:1} عند C_L = {a_clstar:2}؛ المدى = {a_range_km:0} كم ({a_range_nmi:0} ميل بحري).', '(L/D)max = {a_ldmax:1} a C_L = {a_clstar:2}; autonomia = {a_range_km:0} km ({a_range_nmi:0} NM).'),
   T('At C_L* the two drag parts are equal (each 0.02), and L/D of 15\u201320 is the range quoted for modern transport aircraft in textbooks.', 'À C_L* les deux traînées sont égales (0,02 chacune), et une finesse de 15\u201320 est l\u2019ordre de grandeur donné par les manuels pour les avions de transport modernes.', 'Con C_L* las dos resistencias son iguales (0,02 cada una), y L/D de 15\u201320 es el rango que dan los libros para aviones de transporte modernos.', 'عند C_L* يتساوى جزءا السحب (0.02 لكل منهما)، وقيم L/D بين 15 و20 هي النطاق المذكور في الكتب لطائرات النقل الحديثة.', 'A C_L* le due resistenze sono uguali (0,02 ciascuna), e L/D di 15\u201320 è l\u2019intervallo indicato nei libri per i moderni aerei da trasporto.'),
   T('Range is linear in L/D and in engine efficiency but only logarithmic in fuel: adding fuel has diminishing returns.', 'L\u2019autonomie est linéaire en finesse et en rendement moteur, mais seulement logarithmique en carburant : ajouter du carburant rapporte de moins en moins.', 'El alcance es lineal en L/D y en eficiencia del motor, pero solo logarítmico en combustible: añadir combustible rinde cada vez menos.', 'المدى خطي في L/D وكفاءة المحرك، لكنه لوغاريتمي فقط في الوقود: إضافة الوقود تعطي عائدًا متناقصًا.', 'L\u2019autonomia è lineare in L/D e nel rendimento del motore, ma solo logaritmica nel carburante: aggiungere carburante rende sempre meno.'),
   'import math\nAR, e, CD0 = 9, 0.8, 0.02\nk = 1/(math.pi*e*AR)\nprint(1/(2*math.sqrt(k*CD0)), math.sqrt(CD0/k))\nV, c, LD, wr = 230, 0.6/3600, 17, 1.25\nprint(V/c*LD*math.log(wr)/1000, "km")'),
 np=[npq(T('With C_D0 = 0.015 (cleaner airframe), same AR and e: (L/D)max?', 'Avec C_D0 = 0,015 (cellule plus propre), mêmes AR et e : (L/D)max ?', 'Con C_D0 = 0,015 (célula más limpia), mismos AR y e: ¿(L/D)max?', 'مع C_D0 = 0.015 (هيكل أنظف) وبنفس AR و e: كم (L/D)max؟', 'Con C_D0 = 0,015 (cellula più pulita), stessi AR ed e: (L/D)max?'), A.ld_max(0.015, 9, 0.8), '',
   [T('(L/D)max = 1/(2\u221a(k C_D0)) with k = {b:5}.', '(L/D)max = 1/(2\u221a(k C_D0)) avec k = {b:5}.', '(L/D)max = 1/(2\u221a(k C_D0)) con k = {b:5}.', '(L/D)max = 1/(2\u221a(k C_D0)) مع k = {b:5}.', '(L/D)max = 1/(2\u221a(k C_D0)) con k = {b:5}.')],
   T('(L/D)max = {a:2}, about 15% better.', '(L/D)max = {a:2}, environ 15 % de mieux.', '(L/D)max = {a:2}, cerca de un 15 % mejor.', '(L/D)max = {a:2}، أفضل بنحو 15%.', '(L/D)max = {a:2}, circa il 15% meglio.'))],
 prac=[(T('Why is c divided by 3600 in the worked example?', 'Pourquoi c est-il divisé par 3600 dans l\u2019exemple ?', '¿Por qué se divide c entre 3600 en el ejemplo?', 'لماذا نقسم c على 3600 في المثال؟', 'Perché c è diviso per 3600 nell\u2019esempio?'), T('TSFC is quoted per hour; V is in m/s, so c must be per second for R to come out in metres.', 'La consommation spécifique est donnée par heure ; V est en m/s, donc c doit être par seconde pour obtenir R en mètres.', 'El TSFC se da por hora; V está en m/s, así que c debe ir por segundo para obtener R en metros.', 'يُذكر الاستهلاك النوعي لكل ساعة؛ و V بوحدة م/ث، لذا يجب أن تكون c لكل ثانية ليخرج R بالأمتار.', 'Il TSFC è dato all\u2019ora; V è in m/s, quindi c deve essere al secondo perché R esca in metri.'))],
 mist=T('Mixing hours and seconds in TSFC; check units before taking the logarithm.', 'Mélanger heures et secondes dans la consommation spécifique ; vérifier les unités avant le logarithme.', 'Mezclar horas y segundos en el TSFC; revisa unidades antes del logaritmo.', 'خلط الساعات والثواني في الاستهلاك النوعي؛ تحقق من الوحدات قبل اللوغاريتم.', 'Mescolare ore e secondi nel TSFC; controlla le unità prima del logaritmo.'))
S[-1]['np'][0]['extra'] = dict(b=A.k_ind(9, 0.8))
sec(id='compress', lv=['ug', 'grad'], refs=['anderson_fa', 'grc'],
 t=T('Compressible flow and normal shocks', 'Écoulement compressible et chocs droits', 'Flujo compresible y ondas de choque normales', 'الجريان الانضغاطي والصدمات العمودية', 'Flusso compressibile e urti normali'),
 eli=T('When a plane goes faster than sound, the air in front can\u2019t get out of the way in time. It piles up into a thin wall called a shock wave: that\u2019s the sonic boom you hear.', 'Quand un avion va plus vite que le son, l\u2019air devant lui n\u2019a pas le temps de s\u2019écarter. Il s\u2019entasse en un mur très fin, l\u2019onde de choc : c\u2019est le bang qu\u2019on entend.', 'Cuando un avión va más rápido que el sonido, el aire de delante no tiene tiempo de apartarse. Se amontona en una pared finísima, la onda de choque: es el estampido que oyes.', 'عندما تسير الطائرة أسرع من الصوت لا يجد الهواء أمامها وقتًا للابتعاد، فيتكدس في جدار رقيق يسمى موجة الصدمة: وهذا هو دوي اختراق حاجز الصوت.', 'Quando un aereo va più veloce del suono, l\u2019aria davanti non fa in tempo a spostarsi. Si ammassa in un muro sottilissimo, l\u2019onda d\u2019urto: è il bang che senti.'),
 obj=T('Derive stagnation (total) temperature and pressure; compute the flow change across a normal shock from the conservation laws.', 'Établir température et pression d\u2019arrêt ; calculer le changement d\u2019écoulement à travers un choc droit par les lois de conservation.', 'Deducir temperatura y presión de remanso; calcular el cambio del flujo a través de un choque normal con las leyes de conservación.', 'اشتقاق درجة الحرارة والضغط الكليين؛ حساب تغير الجريان عبر صدمة عمودية من قوانين الحفظ.', 'Ricavare temperatura e pressione di ristagno; calcolare la variazione del flusso attraverso un urto normale con le leggi di conservazione.'),
 pre=T('Energy equation, isentropic relations, solving simultaneous nonlinear equations.', 'Équation de l\u2019énergie, relations isentropiques, systèmes d\u2019équations non linéaires.', 'Ecuación de la energía, relaciones isentrópicas, sistemas no lineales.', 'معادلة الطاقة، العلاقات المتساوية الإنتروبيا، حل معادلات غير خطية متزامنة.', 'Equazione dell\u2019energia, relazioni isentropiche, sistemi non lineari.'),
 body=T('Above about Mach 0.3, air density changes noticeably with speed. At supersonic speed, a shock is a sudden jump that conserves mass, momentum and energy but loses total pressure (entropy rises).', 'Au-delà de Mach 0,3 environ, la densité de l\u2019air varie nettement avec la vitesse. En supersonique, un choc est un saut brutal qui conserve masse, quantité de mouvement et énergie mais perd de la pression totale (l\u2019entropie augmente).', 'Por encima de Mach 0,3 la densidad del aire cambia notablemente con la velocidad. En supersónico, un choque es un salto brusco que conserva masa, cantidad de movimiento y energía pero pierde presión total (la entropía sube).', 'فوق ماخ 0.3 تقريبًا تتغير كثافة الهواء ملحوظًا مع السرعة. وفي السرعات فوق الصوتية تكون الصدمة قفزة مفاجئة تحفظ الكتلة والزخم والطاقة لكنها تفقد من الضغط الكلي (تزداد الإنتروبيا).', 'Oltre circa Mach 0,3 la densità dell\u2019aria cambia sensibilmente con la velocità. In supersonico un urto è un salto brusco che conserva massa, quantità di moto ed energia ma perde pressione totale (l\u2019entropia aumenta).'),
 steps=[(r'c_pT+\tfrac12V^2=c_pT_0\;\Rightarrow\;\frac{T_0}{T}=1+\frac{\gamma-1}{2}M^2', T('Steady energy equation with a = \u221a(\u03b3RT).', 'Équation de l\u2019énergie stationnaire avec a = \u221a(\u03b3RT).', 'Ecuación de la energía estacionaria con a = \u221a(\u03b3RT).', 'معادلة الطاقة المستقرة مع a = \u221a(\u03b3RT).', 'Equazione dell\u2019energia stazionaria con a = \u221a(\u03b3RT).')),
        (r'\frac{p_0}{p}=\left(\frac{T_0}{T}\right)^{\gamma/(\gamma-1)}', T('Isentropic deceleration to rest.', 'Ralentissement isentropique jusqu\u2019à l\u2019arrêt.', 'Deceleración isentrópica hasta el reposo.', 'تباطؤ متساوي الإنتروبيا حتى السكون.', 'Decelerazione isentropica fino all\u2019arresto.')),
        (r'\rho_1u_1=\rho_2u_2,\quad p_1+\rho_1u_1^2=p_2+\rho_2u_2^2,\quad h_1+\tfrac12u_1^2=h_2+\tfrac12u_2^2', T('Conservation across the shock.', 'Conservation à travers le choc.', 'Conservación a través del choque.', 'الحفظ عبر الصدمة.', 'Conservazione attraverso l\u2019urto.')),
        (r'M_2^2=\frac{1+\frac{\gamma-1}{2}M_1^2}{\gamma M_1^2-\frac{\gamma-1}{2}},\qquad \frac{p_2}{p_1}=1+\frac{2\gamma}{\gamma+1}(M_1^2-1)', T('Normal-shock relations (solve the three equations).', 'Relations du choc droit (résoudre les trois équations).', 'Relaciones del choque normal (resolver las tres ecuaciones).', 'علاقات الصدمة العمودية (بحل المعادلات الثلاث).', 'Relazioni dell\u2019urto normale (risolvere le tre equazioni).'))],
 we=we(T('Air (\u03b3 = 1.4) at M\u2081 = 2.0 meets a normal shock.', 'Air (\u03b3 = 1,4) à M\u2081 = 2,0 face à un choc droit.', 'Aire (\u03b3 = 1,4) a M\u2081 = 2,0 ante un choque normal.', 'هواء (\u03b3 = 1.4) عند M\u2081 = 2.0 يواجه صدمة عمودية.', 'Aria (\u03b3 = 1,4) a M\u2081 = 2,0 incontra un urto normale.'),
   T('T\u2080/T and p\u2080/p upstream; M\u2082, p\u2082/p\u2081 and the total-pressure ratio p\u2080\u2082/p\u2080\u2081.', 'T\u2080/T et p\u2080/p en amont ; M\u2082, p\u2082/p\u2081 et le rapport des pressions totales p\u2080\u2082/p\u2080\u2081.', 'T\u2080/T y p\u2080/p aguas arriba; M\u2082, p\u2082/p\u2081 y la razón de presiones totales p\u2080\u2082/p\u2080\u2081.', 'T\u2080/T و p\u2080/p قبل الصدمة؛ و M\u2082 و p\u2082/p\u2081 ونسبة الضغط الكلي p\u2080\u2082/p\u2080\u2081.', 'T\u2080/T e p\u2080/p a monte; M\u2082, p\u2082/p\u2081 e il rapporto delle pressioni totali p\u2080\u2082/p\u2080\u2081.'),
   T('Isentropic relations upstream, normal-shock relations across, isentropic again downstream.', 'Relations isentropiques en amont, relations de choc à travers, isentropiques en aval.', 'Isentrópicas aguas arriba, relaciones de choque a través, isentrópicas aguas abajo.', 'علاقات متساوية الإنتروبيا قبل الصدمة، وعلاقات الصدمة عبرها، ثم متساوية الإنتروبيا بعدها.', 'Isentropiche a monte, relazioni d\u2019urto attraverso, isentropiche a valle.'),
   ['T\u2080/T = 1 + 0.2 \u00b7 4 = {a_T0T:3}', 'p\u2080/p = 1.8^3.5 = {a_p0p:4}', 'M\u2082 = {a_M2:5}', 'p\u2082/p\u2081 = 1 + (2.8/2.4)(4 \u2212 1) = {a_p21:3}', 'p\u2080\u2082/p\u2080\u2081 = {a_p0r:5}'],
   T('M\u2082 = {a_M2:4}, p\u2082/p\u2081 = {a_p21:2}, p\u2080\u2082/p\u2080\u2081 = {a_p0r:4}.', 'M\u2082 = {a_M2:4}, p\u2082/p\u2081 = {a_p21:2}, p\u2080\u2082/p\u2080\u2081 = {a_p0r:4}.', 'M\u2082 = {a_M2:4}, p\u2082/p\u2081 = {a_p21:2}, p\u2080\u2082/p\u2080\u2081 = {a_p0r:4}.', 'M\u2082 = {a_M2:4}، p\u2082/p\u2081 = {a_p21:2}، p\u2080\u2082/p\u2080\u2081 = {a_p0r:4}.', 'M\u2082 = {a_M2:4}, p\u2082/p\u2081 = {a_p21:2}, p\u2080\u2082/p\u2080\u2081 = {a_p0r:4}.'),
   T('Standard normal-shock tables (NACA Report 1135) list 0.5774, 4.500 and 0.7209 at M = 2. Flow behind a normal shock is always subsonic, and total pressure always drops.', 'Les tables classiques de choc droit (rapport NACA 1135) donnent 0,5774, 4,500 et 0,7209 à M = 2. L\u2019écoulement derrière un choc droit est toujours subsonique et la pression totale baisse toujours.', 'Las tablas clásicas de choque normal (informe NACA 1135) dan 0,5774, 4,500 y 0,7209 a M = 2. Tras un choque normal el flujo siempre es subsónico y la presión total siempre baja.', 'تذكر جداول الصدمة العمودية القياسية (تقرير NACA رقم 1135) القيم 0.5774 و4.500 و0.7209 عند M = 2. والجريان خلف الصدمة العمودية دون صوتي دائمًا، والضغط الكلي ينخفض دائمًا.', 'Le tabelle classiche dell\u2019urto normale (rapporto NACA 1135) danno 0,5774, 4,500 e 0,7209 a M = 2. Dietro un urto normale il flusso è sempre subsonico e la pressione totale cala sempre.'),
   T('Losing 28% of total pressure is why supersonic inlets use several oblique shocks instead of one normal shock.', 'Perdre 28 % de pression totale explique pourquoi les entrées d\u2019air supersoniques utilisent plusieurs chocs obliques plutôt qu\u2019un choc droit.', 'Perder un 28 % de presión total explica por qué las tomas supersónicas usan varios choques oblicuos en vez de uno normal.', 'فقدان 28% من الضغط الكلي هو سبب استخدام مآخذ الهواء فوق الصوتية عدة صدمات مائلة بدل صدمة عمودية واحدة.', 'Perdere il 28% di pressione totale spiega perché le prese d\u2019aria supersoniche usano più urti obliqui invece di un urto normale.'),
   'import math\ng, M1 = 1.4, 2.0\nt = lambda M: 1 + (g-1)/2*M*M\nM2 = math.sqrt(t(M1) / (g*M1**2 - (g-1)/2))\np21 = 1 + 2*g/(g+1)*(M1**2 - 1)\np0r = p21 * t(M2)**(g/(g-1)) / t(M1)**(g/(g-1))\nprint(t(M1), t(M1)**3.5, M2, p21, p0r)'),
 np=[npq(T('Static-to-total pressure: p\u2080/p at M = 1 (\u03b3 = 1.4)?', 'Rapport p\u2080/p à M = 1 (\u03b3 = 1,4) ?', '¿p\u2080/p a M = 1 (\u03b3 = 1,4)?', 'كم p\u2080/p عند M = 1 (\u03b3 = 1.4)؟', 'p\u2080/p a M = 1 (\u03b3 = 1,4)?'), A.isentropic(1.0)[1], '',
   [T('T\u2080/T = 1.2 at M = 1.', 'T\u2080/T = 1,2 à M = 1.', 'T\u2080/T = 1,2 a M = 1.', 'T\u2080/T = 1.2 عند M = 1.', 'T\u2080/T = 1,2 a M = 1.'), T('Raise to the power \u03b3/(\u03b3\u22121) = 3.5.', 'Élever à la puissance \u03b3/(\u03b3\u22121) = 3,5.', 'Elevar a la potencia \u03b3/(\u03b3\u22121) = 3,5.', 'ارفع إلى القوة \u03b3/(\u03b3\u22121) = 3.5.', 'Elevare alla potenza \u03b3/(\u03b3\u22121) = 3,5.')],
   T('p\u2080/p = 1.2^3.5 = {a:4} (the "critical" ratio, about 1.89).', 'p\u2080/p = 1,2^3,5 = {a:4} (le rapport « critique », environ 1,89).', 'p\u2080/p = 1,2^3,5 = {a:4} (la razón «crítica», unos 1,89).', 'p\u2080/p = 1.2^3.5 = {a:4} (النسبة «الحرجة»، نحو 1.89).', 'p\u2080/p = 1,2^3,5 = {a:4} (il rapporto «critico», circa 1,89).'))],
 prac=[(T('Can a normal shock occur in subsonic flow?', 'Un choc droit peut-il se produire en subsonique ?', '¿Puede haber un choque normal en flujo subsónico?', 'هل يمكن أن تحدث صدمة عمودية في جريان دون صوتي؟', 'Può verificarsi un urto normale in flusso subsonico?'), T('No: for M\u2081 < 1 the relations would require entropy to decrease, violating the second law.', 'Non : pour M\u2081 < 1 les relations exigeraient une baisse d\u2019entropie, contraire au second principe.', 'No: con M\u2081 < 1 las relaciones exigirían que la entropía baje, contra el segundo principio.', 'لا: عندما M\u2081 < 1 تتطلب العلاقات تناقص الإنتروبيا، وهذا يخالف القانون الثاني.', 'No: per M\u2081 < 1 le relazioni richiederebbero una diminuzione di entropia, contro il secondo principio.'))],
 mist=T('Applying isentropic relations across the shock itself. Total pressure is not conserved through a shock.', 'Appliquer les relations isentropiques à travers le choc lui-même. La pression totale n\u2019est pas conservée dans un choc.', 'Aplicar relaciones isentrópicas a través del propio choque. La presión total no se conserva en un choque.', 'تطبيق العلاقات المتساوية الإنتروبيا عبر الصدمة نفسها. الضغط الكلي لا يُحفظ عبر الصدمة.', 'Applicare le relazioni isentropiche attraverso l\u2019urto stesso. La pressione totale non si conserva in un urto.'))
sec(id='prop', lv=['ug'], refs=['mattingly', 'grc'],
 t=T('Jet propulsion: thrust and the Brayton cycle', 'Propulsion à réaction : poussée et cycle de Brayton', 'Propulsión a chorro: empuje y ciclo Brayton', 'الدفع النفاث: الدفع ودورة برايتون', 'Propulsione a getto: spinta e ciclo Brayton'),
 eli=T('A jet engine sucks in air, squeezes it, burns fuel to make it very hot, and blasts it out the back faster than it came in. Pushing air backward pushes the plane forward.', 'Un réacteur aspire de l\u2019air, le comprime, brûle du carburant pour le chauffer énormément et le rejette derrière plus vite qu\u2019il n\u2019est entré. Pousser l\u2019air vers l\u2019arrière pousse l\u2019avion vers l\u2019avant.', 'Un reactor aspira aire, lo comprime, quema combustible para calentarlo mucho y lo expulsa por detrás más rápido de lo que entró. Empujar el aire hacia atrás empuja el avión hacia delante.', 'يمتص المحرك النفاث الهواء ويضغطه ويحرق الوقود ليسخنه كثيرًا ثم يقذفه من الخلف أسرع مما دخل. دفع الهواء إلى الخلف يدفع الطائرة إلى الأمام.', 'Un motore a getto aspira aria, la comprime, brucia carburante per scaldarla molto e la spara dietro più veloce di come è entrata. Spingere l\u2019aria indietro spinge l\u2019aereo avanti.'),
 obj=T('Derive thrust from the momentum equation; derive ideal Brayton-cycle efficiency as a function of pressure ratio.', 'Établir la poussée par l\u2019équation de quantité de mouvement ; établir le rendement idéal du cycle de Brayton en fonction du taux de compression.', 'Deducir el empuje con la ecuación de cantidad de movimiento; deducir el rendimiento ideal del ciclo Brayton según la relación de compresión.', 'اشتقاق الدفع من معادلة الزخم؛ اشتقاق الكفاءة المثالية لدورة برايتون بدلالة نسبة الضغط.', 'Ricavare la spinta dall\u2019equazione della quantità di moto; ricavare il rendimento ideale del ciclo Brayton in funzione del rapporto di compressione.'),
 pre=T('Control volumes, first law of thermodynamics, isentropic relations.', 'Volumes de contrôle, premier principe, relations isentropiques.', 'Volúmenes de control, primer principio, relaciones isentrópicas.', 'حجوم التحكم، القانون الأول للديناميكا الحرارية، العلاقات المتساوية الإنتروبيا.', 'Volumi di controllo, primo principio, relazioni isentropiche.'),
 body=T('The engine is a heat engine (Brayton cycle) that turns fuel energy into a fast jet. Higher compressor pressure ratio means higher thermal efficiency, which is why modern engines compress air 30\u201350 times.', 'Le moteur est une machine thermique (cycle de Brayton) qui transforme l\u2019énergie du carburant en jet rapide. Un taux de compression plus élevé donne un meilleur rendement thermique : d\u2019où les compressions de 30 à 50 des moteurs modernes.', 'El motor es una máquina térmica (ciclo Brayton) que convierte la energía del combustible en un chorro rápido. Mayor relación de compresión significa mayor rendimiento térmico: por eso los motores modernos comprimen el aire 30\u201350 veces.', 'المحرك آلة حرارية (دورة برايتون) تحوّل طاقة الوقود إلى نفث سريع. نسبة ضغط أعلى تعني كفاءة حرارية أعلى، ولهذا تضغط المحركات الحديثة الهواء من 30 إلى 50 مرة.', 'Il motore è una macchina termica (ciclo Brayton) che trasforma l\u2019energia del carburante in un getto veloce. Un rapporto di compressione più alto dà un rendimento termico maggiore: per questo i motori moderni comprimono l\u2019aria 30\u201350 volte.'),
 steps=[(r'F=\dot m\,(V_e-V_0)+(p_e-p_0)A_e', T('Momentum balance on the engine (fuel mass neglected).', 'Bilan de quantité de mouvement sur le moteur (masse de carburant négligée).', 'Balance de cantidad de movimiento en el motor (masa de combustible despreciada).', 'توازن الزخم على المحرك (بإهمال كتلة الوقود).', 'Bilancio della quantità di moto sul motore (massa di carburante trascurata).')),
        (r'\eta_{th}=1-\frac{q_{out}}{q_{in}}=1-\frac{T_4-T_1}{T_3-T_2}', T('Heat in at constant pressure (2\u21923), out (4\u21921).', 'Chaleur reçue à pression constante (2\u21923), rejetée (4\u21921).', 'Calor aportado a presión constante (2\u21923), cedido (4\u21921).', 'حرارة داخلة عند ضغط ثابت (2\u21923) وخارجة (4\u21921).', 'Calore entrante a pressione costante (2\u21923), uscente (4\u21921).')),
        (r'\frac{T_2}{T_1}=\frac{T_3}{T_4}=\pi_c^{(\gamma-1)/\gamma}\;\Rightarrow\;\eta_{th}=1-\pi_c^{-(\gamma-1)/\gamma}', T('Isentropic compression and expansion share the same pressure ratio.', 'Compression et détente isentropiques ont le même rapport de pression.', 'Compresión y expansión isentrópicas comparten la misma razón de presiones.', 'الانضغاط والتمدد المتساويا الإنتروبيا لهما نسبة الضغط نفسها.', 'Compressione ed espansione isentropiche hanno lo stesso rapporto di pressione.'))],
 we=we(T('Ideal Brayton cycle, \u03b3 = 1.4, compressor pressure ratio \u03c0_c = 30. Generic jet: \u1e41 = 100 kg/s, V\u2080 = 250 m/s, V_e = 600 m/s, p_e = p\u2080.', 'Cycle de Brayton idéal, \u03b3 = 1,4, taux de compression \u03c0_c = 30. Jet générique : \u1e41 = 100 kg/s, V\u2080 = 250 m/s, V_e = 600 m/s, p_e = p\u2080.', 'Ciclo Brayton ideal, \u03b3 = 1,4, relación de compresión \u03c0_c = 30. Reactor genérico: \u1e41 = 100 kg/s, V\u2080 = 250 m/s, V_e = 600 m/s, p_e = p\u2080.', 'دورة برايتون مثالية، \u03b3 = 1.4، نسبة ضغط الضاغط \u03c0_c = 30. نفاثة عامة: \u1e41 = 100 كغ/ث، V\u2080 = 250 م/ث، V_e = 600 م/ث، p_e = p\u2080.', 'Ciclo Brayton ideale, \u03b3 = 1,4, rapporto di compressione \u03c0_c = 30. Jet generico: \u1e41 = 100 kg/s, V\u2080 = 250 m/s, V_e = 600 m/s, p_e = p\u2080.'),
   T('Thermal efficiency and thrust.', 'Rendement thermique et poussée.', 'Rendimiento térmico y empuje.', 'الكفاءة الحرارية والدفع.', 'Rendimento termico e spinta.'),
   T('Use the two derived formulas.', 'Utiliser les deux formules établies.', 'Usar las dos fórmulas deducidas.', 'نستخدم الصيغتين المشتقتين.', 'Usare le due formule ricavate.'),
   ['(\u03b3\u22121)/\u03b3 = 0.2857', '\u03b7 = 1 \u2212 30^(\u22120.2857) = {a_eta30:4}', 'F = 100 \u00b7 (600 \u2212 250) = {a_thrust_kN:1} kN'],
   T('\u03b7 = {a_eta30:3} ({a_eta30_pct:1}%); F = {a_thrust_kN:0} kN.', '\u03b7 = {a_eta30:3} ({a_eta30_pct:1} %) ; F = {a_thrust_kN:0} kN.', '\u03b7 = {a_eta30:3} ({a_eta30_pct:1} %); F = {a_thrust_kN:0} kN.', '\u03b7 = {a_eta30:3} ({a_eta30_pct:1}%)؛ F = {a_thrust_kN:0} كيلونيوتن.', '\u03b7 = {a_eta30:3} ({a_eta30_pct:1}%); F = {a_thrust_kN:0} kN.'),
   T('At \u03c0_c = 10 the formula gives {a_eta10:3}: efficiency rises with pressure ratio, but ideally only; real components lose some of it.', 'À \u03c0_c = 10 la formule donne {a_eta10:3} : le rendement croît avec le taux de compression, mais en idéal seulement ; les composants réels en perdent une partie.', 'Con \u03c0_c = 10 la fórmula da {a_eta10:3}: el rendimiento crece con la compresión, pero solo en el caso ideal; los componentes reales pierden parte.', 'عند \u03c0_c = 10 تعطي الصيغة {a_eta10:3}: تزداد الكفاءة مع نسبة الضغط، لكن في الحالة المثالية فقط؛ والمكونات الحقيقية تفقد جزءًا منها.', 'Con \u03c0_c = 10 la formula dà {a_eta10:3}: il rendimento cresce col rapporto di compressione, ma solo idealmente; i componenti reali ne perdono una parte.'),
   T('Thrust needs V_e > V\u2080: big fans moving lots of air slowly (high bypass) are more efficient than small fast jets, which is why airliners use turbofans.', 'La poussée exige V_e > V\u2080 : de grandes soufflantes qui déplacent beaucoup d\u2019air lentement (fort taux de dilution) sont plus efficaces que de petits jets rapides, d\u2019où les turbofans des avions de ligne.', 'El empuje exige V_e > V\u2080: grandes fans que mueven mucho aire despacio (alto bypass) son más eficientes que chorros pequeños y rápidos; por eso los aviones de línea usan turbofanes.', 'يتطلب الدفع V_e > V\u2080: المراوح الكبيرة التي تحرك كثيرًا من الهواء ببطء (نسبة تجاوز عالية) أكفأ من النفثات الصغيرة السريعة، ولهذا تستخدم الطائرات التجارية المحركات المروحية التوربينية.', 'La spinta richiede V_e > V\u2080: grandi fan che muovono molta aria lentamente (alto rapporto di diluizione) sono più efficienti di getti piccoli e veloci; per questo gli aerei di linea usano turbofan.'),
   'g, pic = 1.4, 30\nprint(1 - pic**(-(g-1)/g))\nmdot, V0, Ve = 100, 250, 600\nprint(mdot*(Ve - V0)/1000, "kN")'),
 np=[npq(T('Ideal Brayton efficiency at \u03c0_c = 40?', 'Rendement idéal de Brayton à \u03c0_c = 40 ?', '¿Rendimiento ideal de Brayton con \u03c0_c = 40?', 'كفاءة برايتون المثالية عند \u03c0_c = 40؟', 'Rendimento ideale di Brayton a \u03c0_c = 40?'), A.brayton_eta(40), '',
   [T('\u03b7 = 1 \u2212 \u03c0_c^(\u22120.2857). Answer as a fraction, not a percentage.', '\u03b7 = 1 \u2212 \u03c0_c^(\u22120,2857). Répondez en fraction, pas en pourcentage.', '\u03b7 = 1 \u2212 \u03c0_c^(\u22120,2857). Responde en fracción, no en porcentaje.', '\u03b7 = 1 \u2212 \u03c0_c^(\u22120.2857). أجب بكسر عشري لا بنسبة مئوية.', '\u03b7 = 1 \u2212 \u03c0_c^(\u22120,2857). Rispondi in frazione, non in percentuale.')],
   T('\u03b7 = 1 \u2212 40^(\u22120.2857) = {a:4}.', '\u03b7 = 1 \u2212 40^(\u22120,2857) = {a:4}.', '\u03b7 = 1 \u2212 40^(\u22120,2857) = {a:4}.', '\u03b7 = 1 \u2212 40^(\u22120.2857) = {a:4}.', '\u03b7 = 1 \u2212 40^(\u22120,2857) = {a:4}.'))],
 prac=[(T('Why not raise the pressure ratio without limit?', 'Pourquoi ne pas augmenter le taux de compression sans limite ?', '¿Por qué no subir la compresión sin límite?', 'لماذا لا نرفع نسبة الضغط بلا حدود؟', 'Perché non aumentare il rapporto di compressione senza limite?'), T('Compressor exit temperature rises too, leaving less room for heat addition before the turbine\u2019s material temperature limit.', 'La température en sortie de compresseur augmente aussi, laissant moins de marge d\u2019apport de chaleur avant la limite de température des matériaux de la turbine.', 'La temperatura a la salida del compresor también sube y deja menos margen para aportar calor antes del límite térmico de los materiales de la turbina.', 'ترتفع أيضًا حرارة خروج الضاغط، فيقل الهامش المتاح لإضافة الحرارة قبل حد حرارة مواد التوربين.', 'Sale anche la temperatura all\u2019uscita del compressore, lasciando meno margine per aggiungere calore prima del limite di temperatura dei materiali della turbina.'))],
 mist=T('Forgetting that thrust depends on V_e \u2212 V\u2080, not V_e alone.', 'Oublier que la poussée dépend de V_e \u2212 V\u2080, pas de V_e seul.', 'Olvidar que el empuje depende de V_e \u2212 V\u2080, no solo de V_e.', 'نسيان أن الدفع يعتمد على V_e \u2212 V\u2080 لا على V_e وحدها.', 'Dimenticare che la spinta dipende da V_e \u2212 V\u2080, non da V_e soltanto.'))
sec(id='stab', lv=['grad'], refs=['etkin', 'mil1797', 'ocw100'],
 t=T('Stability and control: the short-period mode', 'Stabilité et contrôle : le mode d\u2019incidence (short period)', 'Estabilidad y control: el modo de periodo corto', 'الاستقرار والتحكم: نمط الدورة القصيرة', 'Stabilità e controllo: il modo di corto periodo'),
 eli=T('Throw a dart: if it wobbles, the feathers at the back straighten it out quickly. An airplane\u2019s tail does the same. Engineers measure how fast the wobble dies away.', 'Lance une fléchette : si elle oscille, les plumes à l\u2019arrière la redressent vite. La queue d\u2019un avion fait pareil. Les ingénieurs mesurent la vitesse à laquelle l\u2019oscillation s\u2019éteint.', 'Lanza un dardo: si se tambalea, las plumas de atrás lo enderezan rápido. La cola de un avión hace lo mismo. Los ingenieros miden lo rápido que se apaga el bamboleo.', 'ارمِ سهمًا: إذا تمايل، تعيده الريش الخلفية إلى الاستقامة بسرعة. ذيل الطائرة يفعل الشيء نفسه. ويقيس المهندسون مدى سرعة زوال التمايل.', 'Lancia una freccetta: se oscilla, le piume dietro la raddrizzano in fretta. La coda di un aereo fa lo stesso. Gli ingegneri misurano quanto in fretta si smorza l\u2019oscillazione.'),
 obj=T('Write the 2-state [\u03b1, q] linear model in state-space form; find its eigenvalues, natural frequency and damping ratio; compare with published flying-qualities limits.', 'Écrire le modèle linéaire à 2 états [\u03b1, q] en représentation d\u2019état ; trouver ses valeurs propres, sa pulsation propre et son amortissement ; comparer aux limites publiées de qualités de vol.', 'Escribir el modelo lineal de 2 estados [\u03b1, q] en espacio de estados; hallar autovalores, frecuencia natural y amortiguamiento; comparar con los límites publicados de cualidades de vuelo.', 'كتابة النموذج الخطي ذي الحالتين [\u03b1، q] في فضاء الحالة؛ إيجاد قيمه الذاتية وتردده الطبيعي ونسبة تخامده؛ ومقارنتها بحدود جودة الطيران المنشورة.', 'Scrivere il modello lineare a 2 stati [\u03b1, q] nello spazio degli stati; trovare autovalori, pulsazione naturale e smorzamento; confrontare con i limiti pubblicati delle qualità di volo.'),
 pre=T('Linear algebra (eigenvalues of a 2\u00d72 matrix), second-order ODEs, complex numbers.', 'Algèbre linéaire (valeurs propres d\u2019une matrice 2\u00d72), EDO du second ordre, nombres complexes.', 'Álgebra lineal (autovalores de una matriz 2\u00d72), EDO de segundo orden, números complejos.', 'الجبر الخطي (القيم الذاتية لمصفوفة 2\u00d72)، المعادلات التفاضلية من الرتبة الثانية، الأعداد المركبة.', 'Algebra lineare (autovalori di una matrice 2\u00d72), EDO del secondo ordine, numeri complessi.'),
 body=T('After a gust, the nose pitches and the angle of attack oscillates for a few seconds. Linearising the equations of motion about steady flight turns this into a 2\u00d72 matrix whose eigenvalues tell you how fast and how well damped the motion is.', 'Après une rafale, le nez tangue et l\u2019incidence oscille quelques secondes. En linéarisant les équations du mouvement autour du vol stabilisé, on obtient une matrice 2\u00d72 dont les valeurs propres disent à quelle vitesse et avec quel amortissement le mouvement se fait.', 'Tras una ráfaga, el morro cabecea y el ángulo de ataque oscila unos segundos. Linealizando las ecuaciones del movimiento en torno al vuelo estable se obtiene una matriz 2\u00d72 cuyos autovalores dicen lo rápido y amortiguado que es el movimiento.', 'بعد هبة ريح يتأرجح الأنف وتتذبذب زاوية الهجوم بضع ثوانٍ. بخطّنة معادلات الحركة حول الطيران المستقر نحصل على مصفوفة 2\u00d72 تخبرنا قيمها الذاتية بسرعة الحركة ومدى تخامدها.', 'Dopo una raffica il muso beccheggia e l\u2019incidenza oscilla per qualche secondo. Linearizzando le equazioni del moto attorno al volo stabilizzato si ottiene una matrice 2\u00d72 i cui autovalori dicono quanto è rapido e smorzato il moto.'),
 steps=[(r'\begin{bmatrix}\dot\alpha\\ \dot q\end{bmatrix}=\begin{bmatrix}Z_\alpha/V & 1\\ M_\alpha+M_{\dot\alpha}Z_\alpha/V & M_q+M_{\dot\alpha}\end{bmatrix}\begin{bmatrix}\alpha\\ q\end{bmatrix}', T('Short-period approximation (speed held constant).', 'Approximation du mode d\u2019incidence (vitesse constante).', 'Aproximación de periodo corto (velocidad constante).', 'تقريب الدورة القصيرة (السرعة ثابتة).', 'Approssimazione di corto periodo (velocità costante).')),
        (r'\det(s\mathbf I-\mathbf A)=s^2-\left(\tfrac{Z_\alpha}{V}+M_q+M_{\dot\alpha}\right)s+\left(\tfrac{Z_\alpha}{V}M_q-M_\alpha\right)=0', T('Characteristic equation.', 'Équation caractéristique.', 'Ecuación característica.', 'المعادلة المميزة.', 'Equazione caratteristica.')),
        (r's^2+2\zeta\omega_ns+\omega_n^2=0\;\Rightarrow\;\omega_n=\sqrt{\tfrac{Z_\alpha}{V}M_q-M_\alpha},\quad \zeta=\frac{-\left(\tfrac{Z_\alpha}{V}+M_q+M_{\dot\alpha}\right)}{2\omega_n}', T('Match to the standard second-order form.', 'Identifier à la forme standard du second ordre.', 'Identificar con la forma estándar de segundo orden.', 'نطابقها مع الصيغة القياسية من الرتبة الثانية.', 'Confrontare con la forma standard del secondo ordine.'))],
 we=we(T('Illustrative derivatives for a generic high-performance jet (not a specific aircraft): Z_\u03b1/V = \u22121.0 s\u207b\u00b9, M_q = \u22121.5 s\u207b\u00b9, M_\u03b1\u0307 = \u22120.3 s\u207b\u00b9, M_\u03b1 = \u22128.0 s\u207b\u00b2.', 'Dérivées illustratives d\u2019un jet générique à hautes performances (pas un avion précis) : Z_\u03b1/V = \u22121,0 s\u207b\u00b9, M_q = \u22121,5 s\u207b\u00b9, M_\u03b1\u0307 = \u22120,3 s\u207b\u00b9, M_\u03b1 = \u22128,0 s\u207b\u00b2.', 'Derivadas ilustrativas de un reactor genérico de altas prestaciones (no un avión concreto): Z_\u03b1/V = \u22121,0 s\u207b\u00b9, M_q = \u22121,5 s\u207b\u00b9, M_\u03b1\u0307 = \u22120,3 s\u207b\u00b9, M_\u03b1 = \u22128,0 s\u207b\u00b2.', 'مشتقات توضيحية لنفاثة عامة عالية الأداء (ليست طائرة بعينها): Z_\u03b1/V = \u22121.0 ث\u207b\u00b9، M_q = \u22121.5 ث\u207b\u00b9، M_\u03b1\u0307 = \u22120.3 ث\u207b\u00b9، M_\u03b1 = \u22128.0 ث\u207b\u00b2.', 'Derivate illustrative di un jet generico ad alte prestazioni (non un aereo specifico): Z_\u03b1/V = \u22121,0 s\u207b\u00b9, M_q = \u22121,5 s\u207b\u00b9, M_\u03b1\u0307 = \u22120,3 s\u207b\u00b9, M_\u03b1 = \u22128,0 s\u207b\u00b2.'),
   T('Eigenvalues, \u03c9_n, \u03b6, and whether \u03b6 meets the Level 1 range.', 'Valeurs propres, \u03c9_n, \u03b6, et si \u03b6 respecte la plage de niveau 1.', 'Autovalores, \u03c9_n, \u03b6 y si \u03b6 cumple el rango de nivel 1.', 'القيم الذاتية و \u03c9_n و \u03b6، وهل تحقق \u03b6 نطاق المستوى 1.', 'Autovalori, \u03c9_n, \u03b6 e se \u03b6 rispetta l\u2019intervallo di livello 1.'),
   T('Form the characteristic polynomial, solve the quadratic, compare with MIL-STD-1797A (Category A, Level 1: 0.35 \u2264 \u03b6 \u2264 1.30).', 'Former le polynôme caractéristique, résoudre l\u2019équation du second degré, comparer à la MIL-STD-1797A (catégorie A, niveau 1 : 0,35 \u2264 \u03b6 \u2264 1,30).', 'Formar el polinomio característico, resolver la cuadrática, comparar con MIL-STD-1797A (categoría A, nivel 1: 0,35 \u2264 \u03b6 \u2264 1,30).', 'نكوّن كثيرة الحدود المميزة، نحل المعادلة التربيعية، ونقارن بالمعيار MIL-STD-1797A (الفئة A، المستوى 1: 0.35 \u2264 \u03b6 \u2264 1.30).', 'Formare il polinomio caratteristico, risolvere la quadratica, confrontare con MIL-STD-1797A (categoria A, livello 1: 0,35 \u2264 \u03b6 \u2264 1,30).'),
   ['s\u00b2 + 2.8 s + 9.5 = 0', 's = {a_sre:2} \u00b1 {a_sim:4} i', '\u03c9_n = \u221a9.5 = {a_wn:4} rad/s', '\u03b6 = 2.8 / (2 \u00b7 {a_wn:4}) = {a_zeta:4}'],
   T('\u03c9_n = {a_wn:2} rad/s, \u03b6 = {a_zeta:2}: inside the Level 1 band.', '\u03c9_n = {a_wn:2} rad/s, \u03b6 = {a_zeta:2} : dans la plage de niveau 1.', '\u03c9_n = {a_wn:2} rad/s, \u03b6 = {a_zeta:2}: dentro de la banda de nivel 1.', '\u03c9_n = {a_wn:2} راديان/ث، \u03b6 = {a_zeta:2}: داخل نطاق المستوى 1.', '\u03c9_n = {a_wn:2} rad/s, \u03b6 = {a_zeta:2}: dentro la banda di livello 1.'),
   T('Both eigenvalues have negative real parts (stable). Product of roots = 9.5 = \u03c9_n\u00b2 and sum = \u22122.8 = \u22122\u03b6\u03c9_n, as Vieta\u2019s formulas require.', 'Les deux valeurs propres ont une partie réelle négative (stable). Produit des racines = 9,5 = \u03c9_n\u00b2 et somme = \u22122,8 = \u22122\u03b6\u03c9_n, comme l\u2019exigent les formules de Viète.', 'Ambos autovalores tienen parte real negativa (estable). Producto de raíces = 9,5 = \u03c9_n\u00b2 y suma = \u22122,8 = \u22122\u03b6\u03c9_n, como exigen las fórmulas de Vieta.', 'للقيمتين الذاتيتين جزء حقيقي سالب (مستقر). حاصل ضرب الجذرين = 9.5 = \u03c9_n\u00b2 ومجموعهما = \u22122.8 = \u22122\u03b6\u03c9_n، كما تقتضي صيغ فييت.', 'Entrambi gli autovalori hanno parte reale negativa (stabile). Prodotto delle radici = 9,5 = \u03c9_n\u00b2 e somma = \u22122,8 = \u22122\u03b6\u03c9_n, come vogliono le formule di Viète.'),
   T('If M_\u03b1 became positive (center of gravity too far aft), \u03c9_n\u00b2 could go negative and the aircraft would diverge: why fly-by-wire control laws are designed with these eigenvalues.', 'Si M_\u03b1 devenait positif (centrage trop arrière), \u03c9_n\u00b2 pourrait devenir négatif et l\u2019avion divergerait : c\u2019est avec ces valeurs propres qu\u2019on conçoit les lois de commandes de vol électriques.', 'Si M_\u03b1 fuera positivo (centro de gravedad muy atrasado), \u03c9_n\u00b2 podría ser negativo y el avión divergiría: por eso las leyes de control fly-by-wire se diseñan con estos autovalores.', 'إذا أصبحت M_\u03b1 موجبة (مركز الثقل متأخر جدًا) فقد تصبح \u03c9_n\u00b2 سالبة وتتباعد الطائرة: ولهذا تُصمم قوانين التحكم الإلكتروني (fly-by-wire) بالاستناد إلى هذه القيم الذاتية.', 'Se M_\u03b1 diventasse positivo (baricentro troppo arretrato), \u03c9_n\u00b2 potrebbe diventare negativo e l\u2019aereo divergerebbe: per questo le leggi di controllo fly-by-wire si progettano con questi autovalori.'),
   'import numpy as np\nZaV, Mq, Mad, Ma = -1.0, -1.5, -0.3, -8.0\nA = np.array([[ZaV, 1.0], [Ma + Mad*ZaV, Mq + Mad]])\nlam = np.linalg.eigvals(A)\nwn = np.sqrt(np.prod(lam).real); zeta = -lam.sum().real / (2*wn)\nprint(lam, wn, zeta)'),
 np=[npq(T('Same aircraft with M_q = \u22120.5 s\u207b\u00b9 (weaker pitch damping): damping ratio \u03b6?', 'Même avion avec M_q = \u22120,5 s\u207b\u00b9 (amortissement en tangage plus faible) : \u03b6 ?', 'Mismo avión con M_q = \u22120,5 s\u207b\u00b9 (menos amortiguamiento en cabeceo): ¿\u03b6?', 'الطائرة نفسها مع M_q = \u22120.5 ث\u207b\u00b9 (تخامد أضعف في الانحدار): كم \u03b6؟', 'Stesso aereo con M_q = \u22120,5 s\u207b\u00b9 (smorzamento in beccheggio più debole): \u03b6?'), A.short_period(-1.0, -0.5, -0.3, -8.0)[1], '',
   [T('New coefficients: s\u00b2 + 1.8 s + 8.5.', 'Nouveaux coefficients : s\u00b2 + 1,8 s + 8,5.', 'Nuevos coeficientes: s\u00b2 + 1,8 s + 8,5.', 'المعاملات الجديدة: s\u00b2 + 1.8 s + 8.5.', 'Nuovi coefficienti: s\u00b2 + 1,8 s + 8,5.'), T('\u03b6 = 1.8/(2\u221a8.5).', '\u03b6 = 1,8/(2\u221a8,5).', '\u03b6 = 1,8/(2\u221a8,5).', '\u03b6 = 1.8/(2\u221a8.5).', '\u03b6 = 1,8/(2\u221a8,5).')],
   T('\u03b6 = {a:3}: below 0.35, so it falls out of Level 1 (pilots would feel the nose bobbing).', '\u03b6 = {a:3} : sous 0,35, hors du niveau 1 (le pilote sentirait le nez osciller).', '\u03b6 = {a:3}: por debajo de 0,35, fuera del nivel 1 (el piloto notaría el morro oscilar).', '\u03b6 = {a:3}: أقل من 0.35، فتخرج من المستوى 1 (سيشعر الطيار بتأرجح الأنف).', '\u03b6 = {a:3}: sotto 0,35, fuori dal livello 1 (il pilota sentirebbe il muso oscillare).'), tol=0.01)],
 prac=[(T('What does a positive real part of an eigenvalue mean physically?', 'Que signifie physiquement une partie réelle positive d\u2019une valeur propre ?', '¿Qué significa físicamente una parte real positiva de un autovalor?', 'ماذا يعني فيزيائيًا جزء حقيقي موجب لقيمة ذاتية؟', 'Cosa significa fisicamente una parte reale positiva di un autovalore?'), T('The disturbance grows exponentially: the aircraft is unstable in that mode.', 'La perturbation croît exponentiellement : l\u2019avion est instable dans ce mode.', 'La perturbación crece exponencialmente: el avión es inestable en ese modo.', 'ينمو الاضطراب أسيًا: الطائرة غير مستقرة في هذا النمط.', 'Il disturbo cresce esponenzialmente: l\u2019aereo è instabile in quel modo.'))],
 mist=T('Sign conventions: M_\u03b1 must be negative for a statically stable aircraft. A sign error flips stability.', 'Conventions de signe : M_\u03b1 doit être négatif pour un avion statiquement stable. Une erreur de signe inverse la stabilité.', 'Convenios de signos: M_\u03b1 debe ser negativo en un avión estáticamente estable. Un error de signo invierte la estabilidad.', 'اصطلاحات الإشارة: يجب أن تكون M_\u03b1 سالبة للطائرة المستقرة سكونيًا. خطأ الإشارة يقلب الاستقرار.', 'Convenzioni di segno: M_\u03b1 deve essere negativo per un aereo staticamente stabile. Un errore di segno inverte la stabilità.'))
sec(id='rotor', lv=['ug', 'grad'], refs=['leishman', 'grc'],
 t=T('Rotorcraft: momentum theory in hover', 'Giravions : théorie de Froude en vol stationnaire', 'Helicópteros: teoría de cantidad de movimiento en vuelo estacionario', 'الطائرات العمودية: نظرية الزخم في التحويم', 'Velivoli ad ala rotante: teoria impulsiva in hovering'),
 eli=T('A helicopter stays up by throwing air down very hard. Bigger blades can throw more air more gently, which takes less power, like using a big shovel instead of a spoon.', 'Un hélicoptère tient en l\u2019air en projetant de l\u2019air vers le bas très fort. De grandes pales projettent plus d\u2019air plus doucement, ce qui demande moins de puissance, comme une grande pelle au lieu d\u2019une cuillère.', 'Un helicóptero se mantiene arriba lanzando aire hacia abajo con fuerza. Palas más grandes lanzan más aire con más suavidad, lo que gasta menos potencia, como una pala grande en vez de una cuchara.', 'تبقى المروحية في الجو بقذف الهواء إلى الأسفل بقوة. الشفرات الأكبر تقذف هواءً أكثر برفق أكبر، فتحتاج قدرة أقل، مثل استخدام مجرفة كبيرة بدل ملعقة.', 'Un elicottero sta su spingendo l\u2019aria verso il basso con forza. Pale più grandi spingono più aria più dolcemente, il che richiede meno potenza, come usare una pala grande invece di un cucchiaio.'),
 obj=T('Derive induced velocity and ideal hover power from momentum conservation; use disk loading and figure of merit.', 'Établir la vitesse induite et la puissance idéale en stationnaire par conservation de la quantité de mouvement ; utiliser la charge du disque et le facteur de mérite.', 'Deducir la velocidad inducida y la potencia ideal en estacionario por conservación de la cantidad de movimiento; usar la carga del disco y la figura de mérito.', 'اشتقاق السرعة المستحثة والقدرة المثالية في التحويم من حفظ الزخم؛ واستخدام حمل القرص ومعامل الجدارة.', 'Ricavare la velocità indotta e la potenza ideale in hovering dalla conservazione della quantità di moto; usare il carico del disco e la figura di merito.'),
 pre=T('Control-volume momentum and energy, Bernoulli\u2019s equation.', 'Quantité de mouvement et énergie sur un volume de contrôle, équation de Bernoulli.', 'Cantidad de movimiento y energía en un volumen de control, ecuación de Bernoulli.', 'الزخم والطاقة على حجم تحكم، معادلة برنولي.', 'Quantità di moto ed energia su un volume di controllo, equazione di Bernoulli.'),
 body=T('Treat the rotor as an "actuator disk" that adds momentum to the air passing through it. The faster the air must be pushed (high disk loading), the more power per newton of thrust.', 'On traite le rotor comme un « disque actuateur » qui ajoute de la quantité de mouvement à l\u2019air qui le traverse. Plus l\u2019air doit être poussé vite (forte charge du disque), plus il faut de puissance par newton de poussée.', 'Se trata el rotor como un «disco actuador» que añade cantidad de movimiento al aire que lo atraviesa. Cuanto más rápido hay que empujar el aire (alta carga del disco), más potencia por newton de empuje.', 'نعامل الدوّار كـ«قرص مشغّل» يضيف زخمًا إلى الهواء المار عبره. كلما وجب دفع الهواء أسرع (حمل قرص عالٍ) زادت القدرة لكل نيوتن من الدفع.', 'Si tratta il rotore come un «disco attuatore» che aggiunge quantità di moto all\u2019aria che lo attraversa. Più velocemente va spinta l\u2019aria (alto carico del disco), più potenza serve per newton di spinta.'),
 steps=[(r'T=\dot m\,w,\qquad \dot m=\rho A v_i', T('Momentum: thrust equals mass flow times the far-wake velocity w.', 'Quantité de mouvement : poussée = débit massique \u00d7 vitesse du sillage lointain w.', 'Cantidad de movimiento: empuje = gasto másico \u00d7 velocidad de la estela lejana w.', 'الزخم: الدفع = معدل تدفق الكتلة \u00d7 سرعة الأثر البعيد w.', 'Quantità di moto: spinta = portata \u00d7 velocità della scia lontana w.')),
        (r'Tv_i=\tfrac12\dot m\,w^2\;\Rightarrow\;w=2v_i', T('Energy: power at the disk equals kinetic energy flux in the wake.', 'Énergie : la puissance au disque égale le flux d\u2019énergie cinétique du sillage.', 'Energía: la potencia en el disco iguala el flujo de energía cinética de la estela.', 'الطاقة: القدرة عند القرص تساوي تدفق الطاقة الحركية في الأثر.', 'Energia: la potenza al disco è uguale al flusso di energia cinetica nella scia.')),
        (r'v_i=\sqrt{\frac{T}{2\rho A}},\qquad P_{ideal}=Tv_i=\frac{T^{3/2}}{\sqrt{2\rho A}},\qquad FM=\frac{P_{ideal}}{P_{actual}}', T('Induced velocity, ideal power, figure of merit.', 'Vitesse induite, puissance idéale, facteur de mérite.', 'Velocidad inducida, potencia ideal, figura de mérito.', 'السرعة المستحثة، القدرة المثالية، معامل الجدارة.', 'Velocità indotta, potenza ideale, figura di merito.'))],
 we=we(T('Generic light helicopter: m = 2700 kg, rotor radius R = 5.1 m, sea level \u03c1 = 1.225 kg/m\u00b3; measured hover power (illustrative) 400 kW.', 'Hélicoptère léger générique : m = 2700 kg, rayon du rotor R = 5,1 m, niveau de la mer \u03c1 = 1,225 kg/m\u00b3 ; puissance mesurée en stationnaire (illustrative) 400 kW.', 'Helicóptero ligero genérico: m = 2700 kg, radio del rotor R = 5,1 m, nivel del mar \u03c1 = 1,225 kg/m\u00b3; potencia medida en estacionario (ilustrativa) 400 kW.', 'مروحية خفيفة عامة: m = 2700 كغ، نصف قطر الدوّار R = 5.1 م، مستوى سطح البحر \u03c1 = 1.225 كغ/م\u00b3؛ قدرة التحويم المقاسة (توضيحية) 400 كيلوواط.', 'Elicottero leggero generico: m = 2700 kg, raggio del rotore R = 5,1 m, livello del mare \u03c1 = 1,225 kg/m\u00b3; potenza misurata in hovering (illustrativa) 400 kW.'),
   T('Disk loading, v_i, P_ideal and FM.', 'Charge du disque, v_i, P_idéale et FM.', 'Carga del disco, v_i, P_ideal y FM.', 'حمل القرص و v_i و P_ideal و FM.', 'Carico del disco, v_i, P_ideale e FM.'),
   T('Thrust equals weight in hover; apply the momentum-theory results.', 'En stationnaire, poussée = poids ; appliquer les résultats de Froude.', 'En estacionario, empuje = peso; aplicar los resultados de la teoría.', 'في التحويم الدفع يساوي الوزن؛ نطبّق نتائج نظرية الزخم.', 'In hovering spinta = peso; applicare i risultati della teoria impulsiva.'),
   ['T = 2700 \u00b7 9.80665 = {a_rT:0} N', 'A = \u03c0 \u00b7 5.1\u00b2 = {a_rA:2} m\u00b2  \u2192  T/A = {a_DL:0} N/m\u00b2', 'v_i = \u221a(T / (2\u03c1A)) = {a_vi:2} m/s', 'P_ideal = T v_i = {a_P:1} kW', 'FM = {a_P:1} / 400 = {a_FM:3}'],
   T('v_i = {a_vi:1} m/s, P_ideal = {a_P:0} kW, FM = {a_FM:2}.', 'v_i = {a_vi:1} m/s, P_idéale = {a_P:0} kW, FM = {a_FM:2}.', 'v_i = {a_vi:1} m/s, P_ideal = {a_P:0} kW, FM = {a_FM:2}.', 'v_i = {a_vi:1} م/ث، P_ideal = {a_P:0} كيلوواط، FM = {a_FM:2}.', 'v_i = {a_vi:1} m/s, P_ideale = {a_P:0} kW, FM = {a_FM:2}.'),
   T('Leishman reports figures of merit of about 0.7\u20130.8 for well-designed rotors, so 0.76 is realistic. FM must be below 1.', 'Leishman indique des facteurs de mérite d\u2019environ 0,7\u20130,8 pour des rotors bien conçus : 0,76 est réaliste. FM doit rester sous 1.', 'Leishman indica figuras de mérito de unos 0,7\u20130,8 para rotores bien diseñados, así que 0,76 es realista. FM debe ser menor que 1.', 'يذكر ليشمان معاملات جدارة نحو 0.7\u20130.8 للدوّارات جيدة التصميم، لذا فإن 0.76 واقعية. ويجب أن يبقى FM أقل من 1.', 'Leishman riporta figure di merito di circa 0,7\u20130,8 per rotori ben progettati, quindi 0,76 è realistico. FM deve restare sotto 1.'),
   T('P grows as T^(3/2) and falls with rotor area, which is why helicopters have long blades and why hovering high and hot costs so much power.', 'P croît comme T^(3/2) et décroît avec la surface du rotor : d\u2019où les longues pales des hélicoptères, et le coût du stationnaire en altitude par forte chaleur.', 'P crece como T^(3/2) y baja con el área del rotor: por eso los helicópteros tienen palas largas y el estacionario en altura y con calor cuesta tanta potencia.', 'تنمو P كـ T^(3/2) وتتناقص مع مساحة الدوّار، ولهذا للمروحيات شفرات طويلة، ولهذا يكلف التحويم في المرتفعات والحر قدرة كبيرة.', 'P cresce come T^(3/2) e cala con l\u2019area del rotore: per questo gli elicotteri hanno pale lunghe e l\u2019hovering in quota e col caldo costa tanta potenza.'),
   'import math\nm, R, rho = 2700, 5.1, 1.225\nT = m*9.80665; A = math.pi*R*R\nvi = math.sqrt(T/(2*rho*A)); P = T*vi\nprint(T/A, vi, P/1000, P/1000/400)'),
 np=[npq(T('Same helicopter with R = 6.0 m: ideal hover power in kW?', 'Même hélicoptère avec R = 6,0 m : puissance idéale en stationnaire, en kW ?', 'Mismo helicóptero con R = 6,0 m: ¿potencia ideal en estacionario, en kW?', 'المروحية نفسها مع R = 6.0 م: القدرة المثالية في التحويم بالكيلوواط؟', 'Stesso elicottero con R = 6,0 m: potenza ideale in hovering, in kW?'), A.hover(2700, 6.0)['P_kW'], 'kW',
   [T('P_ideal = T^(3/2) / \u221a(2\u03c1A).', 'P_idéale = T^(3/2) / \u221a(2\u03c1A).', 'P_ideal = T^(3/2) / \u221a(2\u03c1A).', 'P_ideal = T^(3/2) / \u221a(2\u03c1A).', 'P_ideale = T^(3/2) / \u221a(2\u03c1A).'), T('P scales as 1/R.', 'P varie comme 1/R.', 'P va como 1/R.', 'تتناسب P مع 1/R.', 'P va come 1/R.')],
   T('A = 113.10 m\u00b2; P_ideal = {a:1} kW (vs {b:1} kW at R = 5.1 m).', 'A = 113,10 m\u00b2 ; P_idéale = {a:1} kW (contre {b:1} kW pour R = 5,1 m).', 'A = 113,10 m\u00b2; P_ideal = {a:1} kW (frente a {b:1} kW con R = 5,1 m).', 'A = 113.10 م\u00b2؛ P_ideal = {a:1} كيلوواط (مقابل {b:1} كيلوواط عند R = 5.1 م).', 'A = 113,10 m\u00b2; P_ideale = {a:1} kW (contro {b:1} kW con R = 5,1 m).'))],
 prac=[(T('Why can FM never reach 1 in reality?', 'Pourquoi FM ne peut-il jamais atteindre 1 en réalité ?', '¿Por qué FM nunca llega a 1 en la realidad?', 'لماذا لا يمكن أن يصل FM إلى 1 في الواقع؟', 'Perché FM non può mai arrivare a 1 nella realtà?'), T('Real rotors also spend power on blade profile drag, non-uniform inflow, tip losses and swirl, which momentum theory ignores.', 'Les rotors réels dépensent aussi de la puissance en traînée de profil des pales, écoulement non uniforme, pertes en bout de pale et rotation du sillage, que la théorie de Froude ignore.', 'Los rotores reales también gastan potencia en resistencia de perfil, flujo no uniforme, pérdidas en punta y giro de la estela, que la teoría ignora.', 'تستهلك الدوّارات الحقيقية أيضًا قدرة في سحب مقطع الشفرات وعدم انتظام التدفق وفقد الأطراف ودوران الأثر، وكلها تتجاهلها نظرية الزخم.', 'I rotori reali spendono potenza anche per resistenza di profilo, flusso non uniforme, perdite d\u2019estremità e rotazione della scia, che la teoria ignora.'))],
 mist=T('Using diameter instead of radius in A = \u03c0R\u00b2.', 'Utiliser le diamètre au lieu du rayon dans A = \u03c0R\u00b2.', 'Usar el diámetro en vez del radio en A = \u03c0R\u00b2.', 'استخدام القطر بدل نصف القطر في A = \u03c0R\u00b2.', 'Usare il diametro invece del raggio in A = \u03c0R\u00b2.'))
S[-1]['np'][0]['extra'] = dict(b=A.hover(2700, 5.1)['P_kW'])
sec(id='cfd', lv=['grad', 'phd'], refs=['anderson_cfd', 'anderson_fa', 'ocw100'],
 t=T('CFD basics: finite differences, accuracy and stability', 'Bases de la CFD : différences finies, précision et stabilité', 'Fundamentos de CFD: diferencias finitas, precisión y estabilidad', 'أساسيات ديناميكا الموائع الحسابية: الفروق المحدودة والدقة والاستقرار', 'Basi di CFD: differenze finite, accuratezza e stabilità'),
 eli=T('A computer can\u2019t see smooth air, so it chops the air into tiny boxes and works out what each box does next, one small time step at a time, like a giant spreadsheet.', 'Un ordinateur ne voit pas l\u2019air comme un tout lisse : il le découpe en minuscules cases et calcule ce que fait chaque case au pas de temps suivant, comme un immense tableur.', 'Un ordenador no ve el aire liso, así que lo divide en cajitas y calcula qué hace cada una en el siguiente instante, como una hoja de cálculo gigante.', 'لا يرى الحاسوب الهواء ناعمًا، فيقسمه إلى صناديق صغيرة ويحسب ما سيفعله كل صندوق في الخطوة الزمنية التالية، مثل جدول بيانات عملاق.', 'Un computer non vede l\u2019aria liscia, quindi la taglia in scatoline e calcola cosa fa ognuna al passo successivo, come un enorme foglio di calcolo.'),
 obj=T('Derive finite-difference formulas and their truncation error from Taylor series; state the explicit stability limit for the heat (diffusion) equation; connect to the Navier\u2013Stokes equations.', 'Établir des formules de différences finies et leur erreur de troncature par Taylor ; énoncer la limite de stabilité explicite de l\u2019équation de la chaleur ; relier aux équations de Navier\u2013Stokes.', 'Deducir fórmulas de diferencias finitas y su error de truncamiento con Taylor; enunciar el límite de estabilidad explícito de la ecuación del calor; conectar con Navier\u2013Stokes.', 'اشتقاق صيغ الفروق المحدودة وخطأ الاقتطاع من متسلسلة تايلور؛ صياغة حد الاستقرار الصريح لمعادلة الحرارة (الانتشار)؛ وربطها بمعادلات نافييه\u2013ستوكس.', 'Ricavare formule alle differenze finite e il loro errore di troncamento con Taylor; enunciare il limite di stabilità esplicito dell\u2019equazione del calore; collegarsi alle equazioni di Navier\u2013Stokes.'),
 pre=T('Taylor series, PDEs (diffusion equation), Fourier modes.', 'Séries de Taylor, EDP (équation de diffusion), modes de Fourier.', 'Series de Taylor, EDP (ecuación de difusión), modos de Fourier.', 'متسلسلات تايلور، المعادلات التفاضلية الجزئية (معادلة الانتشار)، أنماط فورييه.', 'Serie di Taylor, EDP (equazione di diffusione), modi di Fourier.'),
 body=T('The Navier\u2013Stokes equations have no general closed-form solution, so engineers discretise them. Two questions decide whether a scheme is useful: how fast does the error shrink as the grid is refined (accuracy), and does the error stay bounded (stability)?', 'Les équations de Navier\u2013Stokes n\u2019ont pas de solution générale en forme fermée : on les discrétise. Deux questions décident de l\u2019utilité d\u2019un schéma : à quelle vitesse l\u2019erreur diminue quand on raffine le maillage (précision), et reste-t-elle bornée (stabilité) ?', 'Las ecuaciones de Navier\u2013Stokes no tienen solución cerrada general, así que se discretizan. Dos preguntas deciden si un esquema sirve: qué tan rápido baja el error al refinar la malla (precisión) y si el error se mantiene acotado (estabilidad).', 'ليس لمعادلات نافييه\u2013ستوكس حل عام مغلق، لذا يجزّئها المهندسون. سؤالان يحددان فائدة المخطط: ما سرعة تناقص الخطأ عند تنعيم الشبكة (الدقة)، وهل يبقى الخطأ محدودًا (الاستقرار)؟', 'Le equazioni di Navier\u2013Stokes non hanno soluzione chiusa generale, quindi si discretizzano. Due domande decidono se uno schema è utile: quanto in fretta cala l\u2019errore raffinando la griglia (accuratezza), e l\u2019errore resta limitato (stabilità)?'),
 steps=[(r'f(x\pm h)=f\pm hf^{\prime}+\tfrac{h^2}{2}f^{\prime\prime}\pm\tfrac{h^3}{6}f^{\prime\prime\prime}+\dots', T('Taylor expansions about x.', 'Développements de Taylor autour de x.', 'Desarrollos de Taylor en torno a x.', 'مفكوكات تايلور حول x.', 'Sviluppi di Taylor attorno a x.')),
        (r'\frac{f(x+h)-f(x)}{h}=f^{\prime}+O(h),\qquad \frac{f(x+h)-f(x-h)}{2h}=f^{\prime}+O(h^2)', T('Forward difference is first order; central is second order.', 'La différence avant est d\u2019ordre 1 ; la centrée d\u2019ordre 2.', 'La diferencia hacia delante es de primer orden; la centrada de segundo.', 'الفرق الأمامي من الرتبة الأولى؛ والمركزي من الرتبة الثانية.', 'La differenza in avanti è del primo ordine; quella centrata del secondo.')),
        (r'u_t=\nu u_{xx}:\quad u_j^{n+1}=u_j^n+r\left(u_{j+1}^n-2u_j^n+u_{j-1}^n\right),\quad r=\frac{\nu\Delta t}{\Delta x^2}\le\frac12', T('Explicit scheme for diffusion; von Neumann analysis gives the stability limit.', 'Schéma explicite pour la diffusion ; l\u2019analyse de von Neumann donne la limite de stabilité.', 'Esquema explícito para la difusión; el análisis de von Neumann da el límite de estabilidad.', 'مخطط صريح للانتشار؛ ويعطي تحليل فون نويمان حد الاستقرار.', 'Schema esplicito per la diffusione; l\u2019analisi di von Neumann dà il limite di stabilità.')),
        (r'\rho\left(\frac{\partial\mathbf u}{\partial t}+\mathbf u\cdot\nabla\mathbf u\right)=-\nabla p+\mu\nabla^2\mathbf u,\qquad \nabla\cdot\mathbf u=0', T('Incompressible Navier\u2013Stokes: the viscous term is this same diffusion operator.', 'Navier\u2013Stokes incompressible : le terme visqueux est ce même opérateur de diffusion.', 'Navier\u2013Stokes incompresible: el término viscoso es este mismo operador de difusión.', 'نافييه\u2013ستوكس غير الانضغاطية: الحد اللزج هو مؤثر الانتشار نفسه.', 'Navier\u2013Stokes incomprimibile: il termine viscoso è lo stesso operatore di diffusione.'))],
 we=we(T('f(x) = sin x at x = 1, step h = 0.1. Exact f\u2032(1) = cos 1 = {a_cos1:6}.', 'f(x) = sin x en x = 1, pas h = 0,1. Valeur exacte f\u2032(1) = cos 1 = {a_cos1:6}.', 'f(x) = sin x en x = 1, paso h = 0,1. Exacto f\u2032(1) = cos 1 = {a_cos1:6}.', 'f(x) = sin x عند x = 1، الخطوة h = 0.1. القيمة الدقيقة f\u2032(1) = cos 1 = {a_cos1:6}.', 'f(x) = sin x in x = 1, passo h = 0,1. Esatto f\u2032(1) = cos 1 = {a_cos1:6}.'),
   T('Forward and central estimates and their errors.', 'Estimations avant et centrée et leurs erreurs.', 'Estimaciones hacia delante y centrada y sus errores.', 'التقديران الأمامي والمركزي وخطآهما.', 'Stime in avanti e centrata e i loro errori.'),
   T('Evaluate both formulas; compare with the leading error terms (h/2)|f\u2033| and (h\u00b2/6)|f\u2034|.', 'Évaluer les deux formules ; comparer aux termes d\u2019erreur dominants (h/2)|f\u2033| et (h\u00b2/6)|f\u2034|.', 'Evaluar ambas fórmulas; comparar con los términos de error dominantes (h/2)|f\u2033| y (h\u00b2/6)|f\u2034|.', 'نحسب الصيغتين؛ ونقارن بحدود الخطأ الرئيسية (h/2)|f\u2033| و (h\u00b2/6)|f\u2034|.', 'Valutare le due formule; confrontare con i termini d\u2019errore dominanti (h/2)|f\u2033| e (h\u00b2/6)|f\u2034|.'),
   ['forward = (sin 1.1 \u2212 sin 1)/0.1 = {a_fwd:6}  \u2192  error {a_efwd:5}', 'central = (sin 1.1 \u2212 sin 0.9)/0.2 = {a_cen:6}  \u2192  error {a_ecen:6}', '(h/2) sin 1 = 0.04207;  (h\u00b2/6) cos 1 = 0.00090'],
   T('Forward error {a_efwd:4}; central error {a_ecen:5}, about 48 times smaller.', 'Erreur avant {a_efwd:4} ; erreur centrée {a_ecen:5}, environ 48 fois plus petite.', 'Error hacia delante {a_efwd:4}; error centrado {a_ecen:5}, unas 48 veces menor.', 'خطأ الفرق الأمامي {a_efwd:4}؛ والمركزي {a_ecen:5}، أصغر بنحو 48 مرة.', 'Errore in avanti {a_efwd:4}; errore centrato {a_ecen:5}, circa 48 volte più piccolo.'),
   T('Both errors match the predicted leading terms (0.0421 and 0.0009); halving h would halve the first and quarter the second.', 'Les deux erreurs correspondent aux termes dominants prévus (0,0421 et 0,0009) ; diviser h par 2 diviserait la première par 2 et la seconde par 4.', 'Ambos errores coinciden con los términos dominantes previstos (0,0421 y 0,0009); dividir h entre 2 reduciría el primero a la mitad y el segundo a la cuarta parte.', 'يطابق الخطآن الحدين الرئيسيين المتوقعين (0.0421 و0.0009)؛ وتنصيف h ينصّف الأول ويقسم الثاني على أربعة.', 'Entrambi gli errori coincidono con i termini dominanti previsti (0,0421 e 0,0009); dimezzando h il primo si dimezza e il secondo si riduce a un quarto.'),
   T('Order of accuracy, not just grid size, decides the cost of a CFD answer; the stability limit r \u2264 1/2 is why explicit solvers need tiny time steps on fine grids.', 'L\u2019ordre de précision, pas seulement la taille du maillage, fixe le coût d\u2019une solution CFD ; la limite r \u2264 1/2 explique les très petits pas de temps des solveurs explicites sur maillage fin.', 'El orden de precisión, no solo el tamaño de malla, decide el coste de una solución CFD; el límite r \u2264 1/2 explica los pasos de tiempo diminutos de los solucionadores explícitos en mallas finas.', 'رتبة الدقة، لا حجم الشبكة وحده، هي ما يحدد كلفة حل CFD؛ وحد الاستقرار r \u2264 1/2 هو سبب حاجة الحلّالات الصريحة إلى خطوات زمنية صغيرة جدًا على الشبكات الدقيقة.', 'L\u2019ordine di accuratezza, non solo la dimensione della griglia, decide il costo di una soluzione CFD; il limite r \u2264 1/2 spiega i passi temporali minuscoli dei solutori espliciti su griglie fini.'),
   'import math\nx, h = 1.0, 0.1\nfwd = (math.sin(x+h) - math.sin(x)) / h\ncen = (math.sin(x+h) - math.sin(x-h)) / (2*h)\nprint(fwd, cen, abs(fwd - math.cos(x)), abs(cen - math.cos(x)))'),
 np=[npq(T('Explicit diffusion scheme with \u03bd = 1\u00d710\u207b\u2075 m\u00b2/s and \u0394x = 1 mm: largest stable \u0394t, in seconds?', 'Schéma explicite de diffusion avec \u03bd = 1\u00d710\u207b\u2075 m\u00b2/s et \u0394x = 1 mm : plus grand \u0394t stable, en secondes ?', 'Esquema explícito de difusión con \u03bd = 1\u00d710\u207b\u2075 m\u00b2/s y \u0394x = 1 mm: ¿mayor \u0394t estable, en segundos?', 'مخطط انتشار صريح مع \u03bd = 1\u00d710\u207b\u2075 م\u00b2/ث و \u0394x = 1 مم: أكبر \u0394t مستقرة بالثواني؟', 'Schema esplicito di diffusione con \u03bd = 1\u00d710\u207b\u2075 m\u00b2/s e \u0394x = 1 mm: massimo \u0394t stabile, in secondi?'), 0.5 * (1e-3) ** 2 / 1e-5, 's',
   [T('r = \u03bd\u0394t/\u0394x\u00b2 \u2264 1/2.', 'r = \u03bd\u0394t/\u0394x\u00b2 \u2264 1/2.', 'r = \u03bd\u0394t/\u0394x\u00b2 \u2264 1/2.', 'r = \u03bd\u0394t/\u0394x\u00b2 \u2264 1/2.', 'r = \u03bd\u0394t/\u0394x\u00b2 \u2264 1/2.'), T('\u0394x = 0.001 m, so \u0394x\u00b2 = 10\u207b\u2076 m\u00b2.', '\u0394x = 0,001 m, donc \u0394x\u00b2 = 10\u207b\u2076 m\u00b2.', '\u0394x = 0,001 m, así que \u0394x\u00b2 = 10\u207b\u2076 m\u00b2.', '\u0394x = 0.001 م، إذن \u0394x\u00b2 = 10\u207b\u2076 م\u00b2.', '\u0394x = 0,001 m, quindi \u0394x\u00b2 = 10\u207b\u2076 m\u00b2.')],
   T('\u0394t \u2264 0.5 \u00b7 10\u207b\u2076 / 10\u207b\u2075 = {a:2} s.', '\u0394t \u2264 0,5 \u00b7 10\u207b\u2076 / 10\u207b\u2075 = {a:2} s.', '\u0394t \u2264 0,5 \u00b7 10\u207b\u2076 / 10\u207b\u2075 = {a:2} s.', '\u0394t \u2264 0.5 \u00b7 10\u207b\u2076 / 10\u207b\u2075 = {a:2} ث.', '\u0394t \u2264 0,5 \u00b7 10\u207b\u2076 / 10\u207b\u2075 = {a:2} s.'))],
 prac=[(T('Halving \u0394x in the explicit diffusion scheme changes the maximum \u0394t by what factor?', 'Diviser \u0394x par 2 dans le schéma explicite change le \u0394t maximal de quel facteur ?', '¿En qué factor cambia el \u0394t máximo al dividir \u0394x entre 2 en el esquema explícito?', 'بأي عامل يتغير أقصى \u0394t عند تنصيف \u0394x في المخطط الصريح؟', 'Dimezzando \u0394x nello schema esplicito, di che fattore cambia il \u0394t massimo?'), T('It is divided by 4, because \u0394t_max \u221d \u0394x\u00b2. Implicit schemes avoid this limit.', 'Il est divisé par 4, car \u0394t_max \u221d \u0394x\u00b2. Les schémas implicites évitent cette limite.', 'Se divide entre 4, porque \u0394t_max \u221d \u0394x\u00b2. Los esquemas implícitos evitan este límite.', 'يُقسم على 4، لأن \u0394t_max \u221d \u0394x\u00b2. والمخططات الضمنية تتجنب هذا الحد.', 'Si divide per 4, perché \u0394t_max \u221d \u0394x\u00b2. Gli schemi impliciti evitano questo limite.'))],
 mist=T('Shrinking h too far in floating point: round-off error grows as h gets tiny, so there is an optimum h.', 'Réduire h trop loin en virgule flottante : l\u2019erreur d\u2019arrondi grandit quand h devient minuscule ; il existe un h optimal.', 'Reducir h demasiado en coma flotante: el error de redondeo crece cuando h es diminuto; hay un h óptimo.', 'تصغير h أكثر من اللازم في الفاصلة العائمة: يزداد خطأ التقريب عندما يصبح h ضئيلًا جدًا، لذا يوجد h أمثل.', 'Ridurre troppo h in virgola mobile: l\u2019errore di arrotondamento cresce quando h diventa minuscolo; esiste un h ottimale.'))
